INSERT INTO `webold_countries` VALUES (1, 'Afghanistan', 'Afganistan/Afqanestan', 'Afghanistan', 'Afghanistan', 'Afghanistan', 'Afghanistan', 'Afganistan', 'Afganistán', 'Afeganistão', '', 'Афганистан', 'AF', 'passolution/countries/1/flag.png', 'passolution/countries/1/cover_image.jpg', '{\"w640\": \"passolution/countries/1/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/1/cover_image/1024w.jpg\"}', 'Asia', 'Kabul', '33332025', '652230', '0', 'Presidential islamic republic', NULL, 'AFN', '93', NULL, NULL, NULL, 1, 'Visumpflichtige Personen benötigen ein Transitvisum.', 'https://www.laenderdaten.info/Asien/Afghanistan/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:24', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (2, 'Ägypten', 'Misr', 'Egypt', 'Égypte', 'Egitto', 'Egypte', 'Egipt', 'Egipto', 'Egito', '', 'Египет', 'EG', 'passolution/countries/2/flag.png', 'passolution/countries/2/cover_image.jpg', '{\"w640\": \"passolution/countries/2/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/2/cover_image/1024w.jpg\"}', 'Africa', 'Cairo', '94666993', '1001450', '2450', 'Presidential republic', NULL, 'EGP', '20', '30.3', '4.7', '72.7', 1, 'Visumpflichtige Personen benötigen ein Transitvisum.Es gelten folgende Ausnahmen : Reisende mit einem Weiterflugticket/ Weiterreiseticket dürfen sich maximal 48 Stunden visumfrei im Transitbereich des Flughafens aufhalten. Diese müssen den Flughafen zwischen 6 und 48 Stunden verlassen. Passagiere, die weniger als 6 Stunden Aufenthalt haben, dürfen nur den Transitbereich verlassen, jedoch nicht den Flughafen.Reisende mit der Staatsbürgerschaft des Iran benötigen ein Transitvisum. Außerdem müssen die Staatsbürgerschaften von Afghanistan, Libanon, Palestina und den Philippinen innerhalb des Transitbereichs bleiben und mit der selben beziehungsweise nächsten Luftverbindung weiterreisen.', 'https://www.laenderdaten.info/Afrika/Aegypten/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:26', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (3, 'Ålandinseln', 'Åland', 'Åland Islands', 'Åland (Îles)', 'Isole Åland', 'Ålandeilanden', 'Wyspy Alandzkie', 'Islas Åland', 'Ilhas Åland', '', 'Аландские острова', 'AX', NULL, NULL, NULL, 'Europe', 'Mariehamn', '29013', '1580', '0', 'Autonomous region of Finland', NULL, 'EUR', '358', '0', '0', '0', 0, NULL, 'https://www.laenderdaten.info/Europa/Aland/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2023-12-13 13:16:44', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (4, 'Albanien', 'Shqipëria', 'Albania', 'Albanie', 'Albania', 'Albanië', 'Albania', 'Albania', 'Albânia', '', 'Албания', 'AL', 'passolution/countries/4/flag.png', 'passolution/countries/4/cover_image.jpg', '{\"w640\": \"passolution/countries/4/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/4/cover_image/1024w.jpg\"}', 'Europe', 'Tirana', '3038594', '28748', '362', 'parliamentary republic', NULL, 'ALL', '355', '13.1', '6.7', '78.3', 1, 'Visumpflichtige Personen benötigen ein Transitvisum.\r\nEs gelten folgende Ausnahmen: \r\nWenn der Reisende ein Weiterflug/ Weiterreiseticket besitzt muss die Reise noch am selben Tag fortgesetzt werden. Es darf sich nur im Transitbereich aufgehalten werden.', 'https://www.laenderdaten.info/Europa/Albanien/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:29', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (5, 'Algerien', 'Al-Jaza’ir/Algérie', 'Algeria', 'Algérie', 'Algeria', 'Algerije', 'Algieria', 'Argelia', 'Argélia', '', 'Алжир', 'DZ', 'passolution/countries/5/flag.png', 'passolution/countries/5/cover_image.jpg', '{\"w640\": \"passolution/countries/5/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/5/cover_image/1024w.jpg\"}', 'Africa', 'Algiers', '40263711', '2381741', '998', 'Presidential republic', NULL, 'DZD', '213', '23', '4.3', '76.8', 1, 'Visumpflichtige Personen benötigen ein Transitvisum.\r\nEs gelten folgende Ausnahmen: \r\nWenn der Reisende ein Weiterflug/ Weiterreiseticket besitzt muss die Reise innerhalb von 24 Stunden fortgesetzt werden. Es darf sich nur im Transitbereich aufgehalten werden. Reisende mit einem von Palästina ausgestelltem Reisedokument benötigen ein Transitvisum.', 'https://www.laenderdaten.info/Afrika/Algerien/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:25', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (6, 'Amerikanisch Samoa', 'Amerika Samoa', 'American Samoa', 'Samoa américaines', 'Samoa Americane', 'Amerikaans Samoa', 'Samoa amerykańskie', 'Samoa Americana', 'Samoa Americana', '', 'Американское Самоа', 'AS', 'passolution/countries/6/flag.png', NULL, NULL, 'Oceania', 'Pago Pago', '54194', '199', '116', 'Presidential democracy (self-governing territory of the US)', NULL, 'USD', '1-684', '22.9', '4.8', '75.4', 1, 'Visumpflichtige Personen benötigen ein Transitvisum.Es gelten folgende Ausnahmen: Visumpflichtige Reisende, die mit dem nächsten Anschluss weiterfliegen und den Transitraum nicht verlassen, benötigen kein Transitvisum.', 'https://www.laenderdaten.info/Ozeanien/Amerikanisch-Samoa/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2023-12-07 14:37:02', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (7, 'Andorra', 'Andorra', 'Andorra', 'Andorre', 'Andorra', 'Andorra', 'Andora', 'Andorra', 'Andorra', '', 'Андорра', 'AD', 'passolution/countries/7/flag.png', 'passolution/countries/7/cover_image.jpg', '{\"w640\": \"passolution/countries/7/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/7/cover_image/1024w.jpg\"}', 'Europe', 'Andorra la Vella', '85660', '468', '0', 'parliamentary democracy', NULL, 'EUR', '376', '7.8', '7.1', '82.8', 1, 'Visumpflichtige Personen benötigen ein Transitvisum.\r\nEs gelten folgende Ausnahmen: \r\nReisende mit den Staatsbürgerschaften der EU-Länder können Visumfrei einreisen.\r\nAlle anderen Reisenden können sich dort bis zu 90 Tagen visumfrei aufhalten.', 'https://www.laenderdaten.info/Europa/Andorra/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:29', 28, '91.36.156.30', 1);
