INSERT INTO `webold_countries` VALUES (17, 'Äthiopien', 'YeItyop´iya', 'Ethiopia', 'Éthiopie', 'Etiopia', 'Ethiopië', 'Etiopia', 'Etiopía', 'Etiópia', '', 'Эфиопия', 'ET', 'passolution/countries/17/flag.png', 'passolution/countries/17/cover_image.jpg', '{\"w640\": \"passolution/countries/17/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/17/cover_image/1024w.jpg\"}', 'Africa', 'Addis Ababa', '102374044', '1104300', '0', 'Federal parliamentary republic', NULL, 'ETB', '251', '36.9', '7.9', '62.2', 1, 'Visumpflichtige Personen benötigen ein Transitvisum.\r\nEs gelten folgende Ausnahmen: \r\nReisende mit einem Weiterreiseticket/ Weiterflugticket können sich bis zu 12 Stunden visumfrei im Transitbereich des Flughafens aufhalten.', 'https://www.laenderdaten.info/Afrika/Aethiopien/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:27', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (18, 'Australien', 'Australia', 'Australia', 'Australie', 'Australia', 'Australië', 'Australia', 'Australia', 'Austrália', '', 'Австралия', 'AU', 'passolution/countries/18/flag.png', 'passolution/countries/18/cover_image.jpg', '{\"w640\": \"passolution/countries/18/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/18/cover_image/1024w.jpg\"}', 'Australia', 'Canberra', '22992654', '7741220', '25760', 'Parliamentary democracy (under constitutional monarchy)', NULL, 'AUD', '61', '12.1', '7.2', '82.2', 1, 'Visumpflichtige Personen benötigen ein Transitvisum.\r\nEs gelten folgende Ausnahmen: \r\nReisende mit einer der folgenden Staatsangehörigkeiten und einem Weiterreiseticket/ Weiterflugticket können sich bis zu 8 Stunden visumfrei im Transitbereich des Flughafens aufhalten:\r\nAndorra, Argentinien, Belgien, Brunei, Bulgarien, Chile, Dänemark, Deutschland, Estland, Finnland, Fiji, Frankreich, Griechenland, Indonesien, Island, Irland, Italien, Japan, Kanada, Kiribati, Demokratische Republik Korea, Kroatien, Lettland, Lichtenstein, Litauen, Luxemburg, Malaysia, Malta, Marshallinseln, Mexiko, Mikronesien, Monaco, Nauru, Niederlande, Norwegen, Oman, Österreich, Palau, Philippinen, Papua Neuguinea, Polen, Portugal, Katar, Rumänien, San Marino, Samoa, Salomonen, Schweden, Schweiz, Singapur, Slowakei, Slowenien, Spanien, Südafrika, Tschechische Republik, Thailand, Tonga, Tuvalu, Vereinigte arabische Emirate, Ungarn, Uruguay, USA, Vanuatu, Zypern.', 'https://www.laenderdaten.info/Australien/Australien/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:27', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (19, 'Bahamas', 'The Bahamas', 'Bahamas', 'Bahamas', 'Bahamas', 'Bahama\'s', 'Bahamy', 'Bahamas', 'Bahamas', '', 'Багамские Острова', 'BS', 'passolution/countries/19/flag.png', 'passolution/countries/19/cover_image.jpg', '{\"w640\": \"passolution/countries/19/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/19/cover_image/1024w.jpg\"}', 'North America', 'Nassau', '327316', '13880', '3542', 'Parliamentary democracy (under constitutional monarchy)', NULL, 'BSD', '1809', '15.4', '7.1', '72.4', 1, 'Visumpflichtige Personen benötigen ein Transitvisum.\r\nEs gelten folgende Ausnahmen: \r\nReisende mit den Staatsbürgerschaften der EU-Länder können sich bis zu 90 Tage visumfrei aufhalten.\r\nReisende mit den Staatsbürgerschaften Albanien, Burkina Faso, Kuba, Dominikanische Republik, Ghana, India, Kasachstan, Südkorea, Kirgistan, Mongolei, Montenegro, Nigeria, Pakistan, Serbien, Tadschikistan, Turkmenistan, Ukraine, Usbekistan, und Vietnam müssen mit einem Weiterreiseticket/ Weiterflugticket am selben Tag wieder ausreisen und dürfen sich nur im Transitbereich des Flughafens aufhalten.\r\nReisende mit den Staatsbürgerschaften Afghanistan, Algerien, Angola, benin, Bhutan, Burundi, Kambodia, Kamerun, Zentralafrikanische Republik, Tschad, Komoren, Kongo, Dem. Rep. Kongo, Elfenbeinküste, Dschibuti, Ägypten, Äquatorialguinea, Eritrea, Äthiopien, Gabun, Guinea, Guinea-Bissau, Indonesien, Iran, Irak, Jordan, Kosovo, Libanon, Liberia, Libyen, Madagaskar, Mauretanien, Nepal, Niger, Palau, Philippinen, Ruanda, Saudi Arabien, Senegal, Somalia, Südsudan, Sudan, Syrien, Thailand, Osttimor, Togo, Tunesien, Macao, Palestina, China und Jemen können sich mit einem Weiterreiseticket/Weiterflugticket bis zu 3 Tage visumfrei im Transitbereich des Flughafens aufhalten.', 'https://www.laenderdaten.info/Amerika/Bahamas/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:28', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (20, 'Bahrain', 'Al-Bahrayn', 'Bahrain', 'Bahreïn', 'Bahrain', 'Bahrein', 'Bahrajn', 'Bahréin', 'Bahrein', '', 'бахрейн', 'BH', 'passolution/countries/20/flag.png', 'passolution/countries/20/cover_image.jpg', '{\"w640\": \"passolution/countries/20/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/20/cover_image/1024w.jpg\"}', 'Asia', 'Manama', '1378904', '760', '161', 'constitutional monarchy', NULL, 'BHD', '973', '13.5', '2.7', '78.9', 1, 'Visumpflichtige Personen benötigen ein Transitvisum.\r\nEs gelten folgende Ausnahmen: \r\nDer Aufenthalt ist visumfrei bis zu 8 Stunden, wenn ein Weiterreiseticket/ Weiterflugticket vorhanden ist. Es darf sich nur im Transitbereich des Flughafens aufgehalten werden.', 'https://www.laenderdaten.info/Asien/Bahrain/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:29', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (21, 'Bangladesch', 'Bangladesh', 'Bangladesh', 'Bangladesh', 'Bangladesh', 'Bangladesh', 'Bangladesz', 'Bangladesh', 'Bangladesh', '', 'Бангладеш', 'BD', 'passolution/countries/21/flag.png', 'passolution/countries/21/cover_image.jpg', '{\"w640\": \"passolution/countries/21/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/21/cover_image/1024w.jpg\"}', 'Asia', 'Dhaka', '156186882', '143998', '580', 'parliamentary republic', NULL, 'BDT', '880', '19', '5.3', '73.2', 1, 'Visumpflichtige Personen benötigen ein Transitvisum.\r\nEs gelten folgende Ausnahmen: Reisende mit einem Weiterreiseticket/ Weiterflugticket können sich bis zu 24 Stunden visumfrei im Transitbereich des Flughafens aufhalten.', 'https://www.laenderdaten.info/Asien/Bangladesch/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:28', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (22, 'Barbados', 'Barbados', 'Barbados', 'Barbade', 'Barbados', 'Barbados', 'Barbados', 'Barbados', 'Barbados', '', 'Барбадос', 'BB', 'passolution/countries/22/flag.png', 'passolution/countries/22/cover_image.jpg', '{\"w640\": \"passolution/countries/22/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/22/cover_image/1024w.jpg\"}', 'North America', 'Bridgetown', '291495', '430', '97', 'Parliamentary democracy (under constitutional monarchy)', NULL, 'BBD', '1809', '11.8', '8.5', '75.3', 1, 'Visumpflichtige Personen benötigen ein Transitvisum.\r\nEs gelten folgende Ausnahmen: \r\nReisende mit einem Weiterreiseticket/ Weiterflugticket können visumfrei einreisen, müssen allerdings noch am selben Tag weiterreisen.\r\nDies gilt nicht für die Staatsbürgerschaften von Algerien und Marokko.', 'https://www.laenderdaten.info/Amerika/Barbados/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:30', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (23, 'Belarus', 'Belarus', 'Belarus', 'Biélorussie', 'Bielorussia', 'Wit-Rusland', 'Białoruś', 'Bielorrusia', 'Bielorrússia', '', 'Беларусь', 'BY', 'passolution/countries/23/flag.png', 'passolution/countries/23/cover_image.jpg', '{\"w640\": \"passolution/countries/23/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/23/cover_image/1024w.jpg\"}', 'Europe', 'Minsk', '9570376', '207600', '0', 'Presidential republic (in fact a dictatorship)', NULL, 'BYR', '375', '10.5', '13.3', '72.7', 1, 'Visumpflichtige Personen benötigen ein Transitvisum.\r\nEs gelten folgende Ausnahmen: \r\nReisende mit einem Weiterreiseticket/ Weiterflugticket können bis zu 24 Stunden visumfrei einreisen, dürfen den Transitbereich im Flughafen jedoch nicht verlassen.', 'https://www.laenderdaten.info/Europa/Belarus/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:29', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (24, 'Belgien', 'België/Belgique', 'Belgium', 'Belgique', 'Belgio', 'België', 'Belgia', 'Bélgica', 'Bélgica', '', 'Бельгия', 'BE', 'passolution/countries/24/flag.png', 'passolution/countries/24/cover_image.jpg', '{\"w640\": \"passolution/countries/24/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/24/cover_image/1024w.jpg\"}', 'Europe', 'Brussels', '11409077', '30528', '67', 'Federal parliamentary republic (under constitutional monarchy)', NULL, 'EUR', '32', '11.4', '9.7', '81', 1, 'Visumpflichtige Personen benötigen ein Transitvisum.\r\nEs gelten folgende Ausnahmen: \r\nReisende mit den Staatsbürgerschaften der EU-Länder haben freien Aufenthalt.\r\nReisende mit den Staatsbürgerschaften von Afghanistan, Bangladesch, Dem. Rep. Kongo, Dominikanische Republik, Eritrea, Äthiopien, Ghana, Guinea, Guinea-Bissau, Iran, Irak, Nepal, Nigeria, Pakistan, Somalia, Südsudan, Sri Lanka, Sudan und Syrien können mit einem Weiterreiseticket/ Weiterflugticket sich bis zu 24 Stunden visumfrei im Transitbereich des Flughafens aufhalten, wenn sie aus einem Nicht-Schengen Land kommen und in ein Nicht-Schengen Land weiterreisen.', 'https://www.laenderdaten.info/Europa/Belgien/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:28', 28, '91.36.156.30', 1);
