INSERT INTO `webold_countries` VALUES (38, 'Burundi', 'Burundi/Uburundi', 'Burundi', 'Burundi', 'Burundi', 'Burundi', 'Burundi', 'Burundi', 'Burundi', '', 'Бурунди', 'BI', 'passolution/countries/38/flag.png', 'passolution/countries/38/cover_image.jpg', '{\"w640\": \"passolution/countries/38/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/38/cover_image/1024w.jpg\"}', 'Africa', 'Bujumbura', '11099298', '27830', '0', 'Presidential republic', NULL, 'BIF', '257', '41.7', '9', '60.5', 1, 'Visumpflichtige Personen benötigen ein Transitvisum.\r\nEs gelten folgende Ausnahmen:\r\nReisende mit einem Weiterreiseticket/ Weiterflugticket können sich visumfrei bis zu dem Anschlussflug im Transitbereich des Flughafens aufhalten.', 'https://www.laenderdaten.info/Afrika/Burundi/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:31', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (39, 'Chile', 'Chile', 'Chile', 'Chili', 'Cile', 'Chili', 'Chile', 'Chile', 'Chile', '', 'Чили', 'CL', 'passolution/countries/39/flag.png', 'passolution/countries/39/cover_image.jpg', '{\"w640\": \"passolution/countries/39/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/39/cover_image/1024w.jpg\"}', 'South America', 'Santiago', '17650114', '756102', '6435', 'Presidential republic', NULL, 'CLP', '56', '13.7', '6.1', '78.8', 1, 'Visumpflichtige Personen benötigen ein Transitvisum.\r\nEs gelten folgende Ausnahmen:\r\nReisende mit einem Weiterreiseticket/ Weiterflugticket bis zu 24 Stunden visumfrei im Transitbereich des Flughafensaufhalten aufhalten', 'https://www.laenderdaten.info/Amerika/Chile/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:32', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (40, 'China', 'Zhongquo', 'China', 'Chine', 'Cina', 'China', 'Chiny', 'China', 'China', '', 'Китай', 'CN', 'passolution/countries/40/flag.png', 'passolution/countries/40/cover_image.jpg', '{\"w640\": \"passolution/countries/40/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/40/cover_image/1024w.jpg\"}', 'Asia', 'Beijing', '1373541278', '9596960', '14500', 'People\'s republic (communist 	one-party system)', NULL, 'CNY', '86', '12.4', '7.7', '75.5', 1, 'Visumpflichtige Personen benötigen ein Transitvisum.\r\n\r\nEs gelten folgende Ausnahmen:\r\n - Reisende mit einem SAR-Pass (Hongkong/Macau), die mit einem bestätigten Weiterflugticket in ein Drittland innerhalb von 24 Stunden über Guangzhou (CAN), Shanghai (PVG) oder Peking (PEK) einreisen, benötigen kein Transitvisum. Sie müssen sich allerdings im Transitbereich des Flughafens aufhalten und die Dokumente zur Weiterreise bereithalten. Diese Ausnahme gilt nicht, wenn Passagiere mit einem Direktflug aus der USA, aus Guam oder den Nördlichen Marianen Inseln einreisen oder per Direktflug dorthin weiterreisen.\r\nEs gibt 2 verschiedene Arten von Aufenthaltsvisas. \r\nDas 24 Stunden Visum, dies gilt nicht für Reisende:\r\nderen Reisepass weniger als 3 Monate gültig ist,\r\ndie nicht an bestimmten Flughäfen einreisen\r\ndie Weiterreisetickets für ein Drittland-Ziel haben\r\ndie China nach 24 Stunden verlassen (Flug, Landweg und Zug) \r\nEin Mehrfachhalt ist für folgende Reisende nicht gestattet wenn : \r\ndie Reisedokumente für weniger als 3 Monate nach Antritt der Reise gültig sind\r\nein chinesischer Visumsverweigerungsstempel im Pass ist\r\ndas chinesische Einwanderungsgesetz in den letzten 5 Jahren verletzt wurde\r\nsich nicht bei der örtlichen Sicherheitsbüro´s angemeldet wurde innerhalb von 24 Stunden in den letzten 2 Jahren\r\nsich nicht an das chinesische Gesetz gehalten wird\r\nReisende die zwischen den USA, Alaska oder Hawaii einreisen sind nicht zulässig und benötigen ein Visum.\r\nEine Ausnahmereglung haben Hong Kong und Macau, diese können den visumfreien Transitaufenthalt in Anspruch nehmen, wenn ihr Reiseziele ihre Heimat ist.\r\nReisende mit der Staatsbürgerschaft Taiwan müssen vor Ort den „Taiwan Compatriot Permit“ beantragen um visumfrei einreisen zu dürfen.\r\nDer Transitbereich des Flughafens darf nicht verlassen werden.\r\n\r\nReisende mit einem SAR-Pass, die nicht im Besitz eines Heimreisetickets oder von chinesischen Reisedokumenten sind können nur über die Flughäfen Beijing Capital International Airport, Guangzhou Baiyun International Airport oder Shanghai Pudong International Airport einreisen und müssen sich im Transitbereich aufhalten.\r\n\r\nReisende die ein Visum benötigen wenn sie durch den Urumqi Diwopu International Airport reisen :\r\nAfghanistan, Aserbaidschan, Iran, Irak, Kasachstan, Kirgistan, Malaysia, Nigeria, Oman, Pakistan, Saudi Arabien, Sri Lanka, Syria, Thailand, Türkei, Jemen.\r\n\r\nReisende die nicht berechtigt sind für einen visumfreien Transitaufenthalt am Xiamen International Airport : \r\nAfghanistan,  Aserbaidschan, Iran, Irak, Kasachstan, Kirgistan, Malaysia, Oman, Pakistan, Saudi Arabien, Sri Lanka, Syrien, Thailand, Türkei, Turkmenistan, Jemen.\r\n\r\nReisende die nicht berechtigt sind für einen visumfreien Transitaufenthalt  am Guangzhou Baiyun International Airport : \r\nSyrien\r\n\r\nAn diesem Flughafen gibt es spezielle Bedingung des visumfreien Transit Aufenthalts: Urumqi Diwopu International Airport, hier muss innerhalb von 2 Stunden wiederausgereist werden! Ein Mehrfachhalt wird ebenfalls nicht erlaubt.\r\n\r\nAn diesen Flughäfen wird ein Transitvisum benötigt	: \r\nFuzhou Changle International Airport\r\nHuangshan Tunxi International Airport\r\nMudanjiang Hailang Airport\r\nShenzhen Bao\'an International Airport\r\nYanji Chaoyangchuan Airport\r\n\r\n\r\nDas 72 Stunden / 144 Stunden Visum gilt, wenn : \r\nüber folgende Orte eingereist wird : Beijing Capital International Airport, Hangzhou International Airport, Nanjing Lukou International Airport, Shanghai Pudong International Airport, Shanghai Hongqiao International Airport, Shijiazhuang Zhengding International Airport, Tianjin Binhai International Airport, Changsha Huanghua International Airport, Chengdu Shuangliu International Airport, Chongqing Jiangbei International Airport, Dalian Zhoushuizi International Airport, Guangzhou Baiyun International Airport, Guilin Liangjiang International Airport, Harbin Taiping International Airport, Qingdao International Airport, Kunming Changshui International Airport, Shenyang Taoxian International Airport, Wuhan Tianhe International Airport, Xi’an Xianyang International Airport, Xiamen Gaoqi International Airport, Shanghai Port International Cruise Terminal, Shanghai Port International Cruise Terminal, Qinhuangdao Port, Tianjin International Cruise Home Port, Beijing West Railway Station, Shanghai Railway Station\r\n\r\nder Reisepass mehr als 3 Monate bei Ankunft gültig ist\r\ndas Ticket zeigt, dass zum ersten Ziel innerhalb von 72 oder 144 Stunden in einem Drittland aufgebrochen werden kann (Hong Kong und Macau gelten als Transitländer)\r\n die Flüge am selben Flughafen ankommen und abheben\r\nder erste Stop in einem Drittland erfolgte\r\n\r\nReisende, die die Bedingungen erfüllen erhalten einen Stempel oder Sticker mit dem Datum der Einreise und der Abreise. \r\nDer Visumfreie Aufenthalt beginnt am nächsten Tag um 00:01. Bei folgenden Flughäfen beginnt das Visum am Einreisetag : Guilin Liangjiang International Airport, Harbin Tapping International Airport, Kunming Changshui International Airport. \r\n\r\nFolgende Reisende, die nicht den Kategorien zuzuordnen sind, ist es nicht möglich visumfrei einzureisen und müssen China nach der Ankunft wieder verlassen wenn : \r\ndie Reisedokumente für weniger als 3 Monate nach Antritt der Reise gültig sind\r\nein chinesischer Visumsverweigerungsstempel im Pass ist\r\ndas chinesische Einwanderungsgesetz in den letzten 5 Jahren verletzt wurde\r\nsich nicht bei der örtlichen Sicherheitsbüro´s angemeldet wurde innerhalb von 24 Stunden in den letzten 2 Jahren\r\nsich nicht an das chinesische Gesetz gehalten wird\r\n\r\n\r\nSchiffsreisende sind ebenfalls nicht berechtigt für das 72/ 144 Stunden Transitvisum, diese müssen mit einem vorher angeforderten Visum einreisen.\r\n\r\nSeit dem 30 Januar 2016 können  Reisende in Shanghai, Jiangsu Provinz, Zhejiang Provinz und Guangdong Provinz für 144 Stunden aufhalten, seit dem 28 Dezember 2017 auch ich in Beijing, Tianjin und Hebei Provinz, seit dem 1 Januar 2018 ebenfalls in den Städten von Shenyang und Dalian in Liaoning Provinz.\r\n\r\nReisende der folgenden Nationalisten sind dazu berechtigt : \r\nAlle europäischen Staaten, Albanien, Argentinien, Australien, Belarus, Bosnien und Herzegovina, Brasilien, Kanada, Chile, Island, Japan, Mazedonien, Mexiko, Monaco, Montenegro, Neu Seeland, Katar, Russland, Südkorea, Schweiz, Ukraine, USA\r\n\r\n\r\nAn diesem Flughafen gibt es spezielle Bedingung des visumfreien Transit Aufenthalts : Urumqi Diwopu International Airport, hier muss innerhalb von 2 Stunden wiederausgereist werden! Ein Mehrfachhalt wird ebenfalls nicht erlaubt.\r\n\r\nAn diesen Flughäfen wird ein Transitvisum benötigt	: \r\nFuzhou Changle International Airport\r\nHuangshan Tunxi International Airport\r\nMudanjiang Hailang Airport\r\nShenzhen Bao\'an International Airport\r\nYanji Chaoyangchuan Airport', 'https://www.laenderdaten.info/Asien/China/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:31', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (41, 'Cookinseln', 'The Cook Islands', 'Cook Islands', 'Cook (Îles Cook)', 'Isole Cook', 'Cookeilanden', 'Wyspy Cooka', 'Islas Cook', 'Ilhas Cook', '', 'Острова Кука', 'CK', 'passolution/countries/41/flag.png', 'passolution/countries/41/cover_image.jpg', '{\"w640\": \"passolution/countries/41/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/41/cover_image/1024w.jpg\"}', 'Oceania', 'Avarua', '9556', '236', '120', 'parliamentary democracy', NULL, 'NZD', '682', '14.1', '8.3', '75.8', 1, 'Visumpflichtige Personen benötigen ein Transitvisum.Es gelten folgende Ausnahmen:Reisende mit einem Weiterreiseticket /Weiterflugticket können sich so lange im Transitbereich aufhalten, bis der Anschlussflug genommen werden kann.', 'https://www.laenderdaten.info/Ozeanien/Cookinseln/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:31', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (42, 'Costa Rica', 'Costa Rica', 'Costa Rica', 'Costa Rica', 'Costa Rica', 'Costa Rica', 'Kostaryka', 'Costa Rica', 'Costa Rica', '', 'Коста-Рика', 'CR', 'passolution/countries/42/flag.png', 'passolution/countries/42/cover_image.jpg', '{\"w640\": \"passolution/countries/42/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/42/cover_image/1024w.jpg\"}', 'Central America', 'San José', '4872543', '51100', '1290', 'Presidential republic', NULL, 'CRC', '506', '15.7', '4.6', '78.6', 1, 'Visumpflichtige Personen benötigen ein Transitvisum.\r\nEs gelten folgende Ausnahmen:\r\nReisende mit einem Weiterreiseticket /Weiterflugticket können sich bis zu 12 Stunden im Transitbereich aufhalten.', 'https://www.laenderdaten.info/Amerika/Costa-Rica/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:32', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (43, 'Curaçao', 'Kòrsou', 'Curacao', 'Curaçao', 'Curacao', 'Curaçao', 'Curacao', 'Curaçao', 'Curaçao', '', 'Кюрасао', 'CW', 'passolution/countries/43/flag.png', 'passolution/countries/43/cover_image.jpg', '{\"w640\": \"passolution/countries/43/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/43/cover_image/1024w.jpg\"}', 'America', NULL, '149035', '444', '364', 'parliamentary republic', NULL, 'ANG', '599-9', '13.8', '8.3', '78.3', 1, 'Visumpflichtige Personen benötigen ein Transitvisum.Es gelten folgende Ausnahmen:Reisende mit einem Weiterreiseticket /Weiterflugticket können sich bis zu 48 Stunden im Transitbereich aufhalten.', 'https://www.laenderdaten.info/Amerika/Curacao/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:32', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (44, 'Dänemark', 'Danmark', 'Denmark', 'Danemark', 'Danimarca', 'Denemarken', 'Dania', 'Dinamarca', 'Dinamarca', '', 'Дания', 'DK', 'passolution/countries/44/flag.png', 'passolution/countries/44/cover_image.jpg', '{\"w640\": \"passolution/countries/44/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/44/cover_image/1024w.jpg\"}', 'Europe', 'Copenhagen', '5593785', '43094', '7314', 'Parliamentary constitutional monarchy', NULL, 'DKK', '45', '10.4', '10.3', '79.4', 1, 'Visumpflichtige Personen benötigen ein Transitvisum.\r\nEs gelten folgende Ausnahmen:\r\nReisende mit einer Staatsbürgerschaft der EU-Mitglieder können sich frei  aufhalten.\r\nReisende mit den Staatsbürgerschaften Afghanistan, Bangladesch, Dem. Rep. Kongo, Eritrea, Äthiopien, Ghana, Iran, Irak, Nigeria ,Pakistan, Somalia, Sri Lanka und Syrien mit einem Weiterreiseticket/ Weiterflugticket müssen am selben Kalendertag wieder ausreisen.', 'https://www.laenderdaten.info/Europa/Daenemark/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:33', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (45, 'Demokratische Republik Kongo', 'République Démocratique du Congo', 'Democratic Republic of the Congo', 'République Démocratique du Congo', 'Repubblica Democratica del Congo', 'Democratische Republiek Congo', 'Demokratyczna Republika Konga', 'República Democrática del Congo', 'República Democrática do Congo', '', 'Демократическая Республика Конго', 'CD', 'passolution/countries/45/flag.png', 'passolution/countries/45/cover_image.jpg', '{\"w640\": \"passolution/countries/45/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/45/cover_image/1024w.jpg\"}', 'Africa', 'Kinshasa', '81331050', '2344858', '37', 'Semi-presidential republic', NULL, 'CDF', '242', '34.2', '9.9', '57.3', 0, NULL, 'https://www.laenderdaten.info/Afrika/Kongo-Kinshasa/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:32', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (46, 'Deutschland', 'Deutschland', 'Germany', 'Allemagne', 'Germania', 'Duitsland', 'Niemcy', 'Alemania', 'Alemanha', '', 'Германия', 'DE', 'passolution/countries/46/flag.png', 'passolution/countries/46/cover_image.jpg', '{\"w640\": \"passolution/countries/46/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/46/cover_image/1024w.jpg\"}', 'Europe', 'Berlin', '80722792', '357022', '2389', 'Federal parliamentary republic', NULL, 'EUR', '49', '8.5', '11.6', '80.7', 1, 'Visumpflichtige Personen benötigen ein Transitvisum.\r\nEs gelten folgende Ausnahmen: \r\nVisumpflichtige Reisende haben die Möglichkeit ein Transitvisum für maximal 5 Tage zu beantragen. Bitte informieren Sie sich vorab bei Ihrer zuständigen Behörde.\r\nReisende mit den Staatsbürgerschaften Afghanistan, Bangladesch, Dem. Rep. Kongo, Eritrea, Äthiopien, Ghana, Indien, Iran, Irak, Libanon, Mali, Nigeria, Pakistan, Südsudan, Sri Lanka, Sudan, Syrien und Türkei dürfen sich maximal 24 Stunden visumfrei im Transitbereich des Flughafens aufhalten, wenn sie einen diplomatischen Reisepass besitzen.\r\nReisende mit den Staatsbürgerschaften Bulgarien, Kanada, Kroatien, Zypern, Irland, Japan, Rumänien und USA dürfen sich nur 24 Stunden im Transitbereich des Flughafens aufhalten, wenn sie zu einem Land reisen, welches kein Schengen-Mitglied ist.\r\nReisende mit der Nationalität Jordans mit einem Weiterreiseticket/ Weiterflugticket dürfen sich maximal 12 Stunden visumfrei im Transitbereich des Flughafens aufhalten, wenn sie eine der beiden Bedingungen erfüllen : Ein Visum für Bulgarien, Kanada, Kroatien, Zypern, Irland, Japan, Rumänien oder USA besitzen oder in Frankfurt(FRA) oder München(MUC) einreisen.', NULL, 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:34', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (47, 'Dominica', 'Dominica', 'Dominica', 'Dominique', 'Dominica', 'Dominica', 'Dominika', 'Dominica', 'Dominica', '', 'Доминика', 'DM', 'passolution/countries/47/flag.png', 'passolution/countries/47/cover_image.jpg', '{\"w640\": \"passolution/countries/47/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/47/cover_image/1024w.jpg\"}', 'North America', 'Roseau', '73757', '751', '148', 'parliamentary republic', NULL, 'XCD', '1809', '15.2', '7.9', '77', 1, 'Visumpflichtige Personen benötigen ein Transitvisum.\r\nEs gelten folgende Ausnahmen: -', 'https://www.laenderdaten.info/Amerika/Dominica/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:33', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (48, 'Dominikanische Republik', 'República Dominicana', 'Dominican Republic', 'République dominicaine', 'Repubblica Dominicana', 'Dominicaanse Republiek', 'Republika Dominikańska', 'República Dominicana', 'República Dominicana', '', 'Доминиканская Республика', 'DO', 'passolution/countries/48/flag.png', 'passolution/countries/48/cover_image.jpg', '{\"w640\": \"passolution/countries/48/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/48/cover_image/1024w.jpg\"}', 'North America', 'Santo Domingo', '10606865', '48670', '1288', 'Presidential republic', NULL, 'DOP', '1809', '18.6', '4.6', '78.1', 1, 'Visumpflichtige Personen benötigen ein Transitvisum.\r\nEs gelten folgende Ausnahmen: \r\nReisende mit einem Weiterreiseticket/ Weiterflugticket müssen noch am selben Tag wieder ausreisen und dürfen sich nur im Transitbereich des Flughafens aufhalten.', 'https://www.laenderdaten.info/Amerika/Dominikanische-Republik/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:33', 28, '91.36.156.30', 1);
