INSERT INTO `webold_countries` VALUES (50, 'Ecuador', 'Ecuador', 'Ecuador', 'Équateur', 'Ecuador', 'Ecuador', 'Ekwador', 'Ecuador', 'Equador', '', 'Эквадор', 'EC', 'passolution/countries/50/flag.png', 'passolution/countries/50/cover_image.jpg', '{\"w640\": \"passolution/countries/50/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/50/cover_image/1024w.jpg\"}', 'South America', 'Quito', '16080778', '283561', '2237', 'Presidential republic', NULL, 'USD', '593', '18.2', '5.1', '76.8', 1, 'Visumpflichtige Personen benötigen ein Transitvisum.\r\nEs gelten folgende Ausnahmen: \r\nReisende mit einem Weiterreiseticket/ Weiterflugticket dürfen sich so lange im Transitbereich des Flughafens aufhalten bis der Anschlussflug abhebt.', 'https://www.laenderdaten.info/Amerika/Ecuador/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:35', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (51, 'El Salvador', 'El Salvador', 'El Salvador', 'Salvador', 'El Salvador', 'El Salvador', 'Salwador', 'El Salvador', 'El Salvador', '', 'Сальвадор', 'SV', 'passolution/countries/51/flag.png', 'passolution/countries/51/cover_image.jpg', '{\"w640\": \"passolution/countries/51/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/51/cover_image/1024w.jpg\"}', 'Central America', 'San Salvador', '6156670', '21041', '307', 'Presidential republic', NULL, 'USD', '503', '16.3', '5.7', '74.7', 1, 'Visumpflichtige Personen benötigen ein Transitvisum.\r\nEs gelten folgende Ausnahmen: \r\nReisende mit einem Weiterreiseticket/ Weiterflugticket dürfen sich bis zu 48 Stunden visumfrei im Transitbereich des Flughafens aufhalten.', 'https://www.laenderdaten.info/Amerika/El-Salvador/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:35', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (52, 'Elfenbeinküste', 'Côte d’Ivoire', 'Ivory Coast', 'Côte d’Ivoire', 'Costa d\'Avorio', 'Ivoorkust', 'Wybrzeże Kości Słoniowej', 'Costa de Marfil', 'Costa do Marfim', '', 'Берег Слоновой Кости', 'CI', 'passolution/countries/52/flag.png', 'passolution/countries/52/cover_image.jpg', '{\"w640\": \"passolution/countries/52/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/52/cover_image/1024w.jpg\"}', 'Africa', 'Yamoussoukro', '23740424', '322463', '515', 'Presidential republic', NULL, 'XOF', '225', '28.2', '9.5', '58.7', 0, 'Visumfrei bei Weiterreise am selben Tag und nicht verlassen des Flughafens.', 'https://www.laenderdaten.info/Afrika/Elfenbeinkueste/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:34', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (53, 'Eritrea', 'Ertra', 'Eritrea', 'Érythrée', 'Eritrea', 'Eritrea', 'Erytrea', 'Eritrea', 'Eritreia', '', 'Эритрея', 'ER', 'passolution/countries/53/flag.png', 'passolution/countries/53/cover_image.jpg', '{\"w640\": \"passolution/countries/53/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/53/cover_image/1024w.jpg\"}', 'Africa', 'Asmara', '5869869', '117600', '2234', 'Presidential republic', NULL, 'ERN', '291', '30.1', '7.3', '64.9', 1, 'Visumpflichtige Personen benötigen ein Transitvisum.\r\nEs gelten folgende Ausnahmen: \r\nReisende mit einem Weiterreiseticket/ Weiterflugticket dürfen sich bis zu 72 Stunden visumfrei im Transitbereich des Flughafens aufhalten.', 'https://www.laenderdaten.info/Afrika/Eritrea/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:34', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (54, 'Estland', 'Eesti', 'Estonia', 'Estonie', 'Estonia', 'Estland', 'Estonia', 'Estonia', 'Estónia', '', 'Эстония', 'EE', 'passolution/countries/54/flag.png', 'passolution/countries/54/cover_image.jpg', '{\"w640\": \"passolution/countries/54/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/54/cover_image/1024w.jpg\"}', 'Europe', 'Tallinn', '1258545', '45228', '3794', 'parliamentary republic', NULL, 'EUR', '372', '10.3', '12.5', '76.7', 1, 'Visumpflichtige Personen benötigen ein Transitvisum.\r\nEs gelten folgende Ausnahmen: \r\nReisende mit den Staatsbürgerschaften der EU-Länder können sich frei aufhalten.\r\nReisende mit einem Weiterreiseticket/ Weiterflugticket der folgenden Staatsbürgerschaften : Afghanistan, Angola, Bangladesch, Dem. Rep. Kongo, Elfenbeinküste, Eritrea, Äthiopien, Ghana, Haiti, Iran, Irak, Liberia, Libyen, Mali, Nigeria, Pakistan, Senegal, Sierra Leone, Somalia, Sri Lanka, Sudan, Syrien, und Togo müssen noch am selben Tag wieder ausreisen und dürfen sich nur im Transitbereich des Flughafens aufhalten.', 'https://www.laenderdaten.info/Europa/Estland/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:34', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (55, 'Falklandinseln', 'Falkland Islands', 'Falkland Islands', 'Malouines (Îles)', 'Isole Falkland', 'Falklandeilanden', 'Falklandy', 'Islas Malvinas', 'Ilhas Malvinas', '', 'Фолклендские острова', 'FK', 'passolution/countries/55/flag.png', 'passolution/countries/55/cover_image.jpg', '{\"w640\": \"passolution/countries/55/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/55/cover_image/1024w.jpg\"}', 'South America', 'Stanley', '2931', '12173', '1288', 'Parliamentary democracy (self-governing territory of the UK)', NULL, 'FKP', '500', '10.9', '4.9', '0', 1, 'Visumpflichtige Personen benötigen ein Transitvisum.Es gelten folgende Ausnahmen: Reisende mit einem Weiterreiseticket/ Weiterflugticket dürfen sich nur im Transitbereich des Flughafens aufhalten innerhalb der nächsten 24 Stunden aufhalten.', 'https://www.laenderdaten.info/Amerika/Falklandinseln/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:34', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (56, 'Färöer-Inseln', 'Føroyar', 'Faroe Islands', 'Féroé (Îles)', 'Isole Faroe', 'Faeröer Eilanden', 'Wyspy Owcze', 'Islas Feroe', 'Ilhas Faroé', '', 'Фарерские острова', 'FO', 'passolution/countries/56/flag.png', 'passolution/countries/56/cover_image.jpg', '{\"w640\": \"passolution/countries/56/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/56/cover_image/1024w.jpg\"}', 'Europe', 'Tórshavn', '50456', '1393', '1117', 'Parliamentary democracy (territory of the Kingdom of Denmark)', NULL, 'DKK', '298', '14', '8.7', '80.4', 1, 'Visumpflichtige Personen benötigen ein Transitvisum.Es gelten folgende Ausnahmen: Für deutsche Staatsbürger visumfrei bei einem Aufenthalt bis zu 90 Tagen.', 'https://www.laenderdaten.info/Europa/Faeroeer-Inseln/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:34', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (57, 'Fidschi', 'Fiji Islands', 'Fiji', 'Fidji', 'Figi', 'Fiji', 'Fidżi', 'Fiji', 'Fiji', '', 'Фиджи', 'FJ', 'passolution/countries/57/flag.png', 'passolution/countries/57/cover_image.jpg', '{\"w640\": \"passolution/countries/57/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/57/cover_image/1024w.jpg\"}', 'Oceania', 'Suva', '915303', '18274', '1129', 'parliamentary republic', NULL, 'FJD', '679', '19', '6.1', '72.7', 1, 'Visumpflichtige Personen benötigen ein Transitvisum.\r\nEs gelten folgende Ausnahmen: \r\nFür Reisende Staatsbürger der EU-Länder ist die Durchreise visumfrei. \r\nReisende anderer Staatsbürgerschaften mit einem Weiterreiseticket/ Weiterflugticket müssen innerhalb der nächsten 3 Stunden wieder ausreisen und dürfen sich nur im Transitbereich des Flughafens aufhalten.', 'https://www.laenderdaten.info/Ozeanien/Fidschi/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:35', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (58, 'Finnland', 'Suomi', 'Finland', 'Finlande', 'Finlandia', 'Finland', 'Finlandia', 'Finlandia', 'Finlândia', '', 'Финляндия', 'FI', 'passolution/countries/58/flag.png', 'passolution/countries/58/cover_image.jpg', '{\"w640\": \"passolution/countries/58/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/58/cover_image/1024w.jpg\"}', 'Europe', 'Helsinki', '5498211', '338145', '1250', 'parliamentary republic', NULL, 'EUR', '358', '10.7', '9.9', '80.9', 1, 'Visumpflichtige Personen benötigen ein Transitvisum.\r\nEs gelten folgende Ausnahmen: \r\nFür Reisende Staatsbürger der EU-Länder dürfen sich frei aufhalten. \r\nReisende der Staatsbürgerschaften Afghanistan, Bangladesch, Dem. Rep. Kongo, Eritrea, Äthiopien, Ghana, Iran, Irak, Nigeria, Pakistan und Sri Lanka dürfen mit einem Weiterreiseticket/ Weiterflugticket sich 24 Stunden im Transitbereich des Flughafens aufhalten.', 'https://www.laenderdaten.info/Europa/Finnland/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:35', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (59, 'Frankreich', 'France', 'France', 'France', 'Francia', 'Frankrijk', 'Francja', 'Francia', 'França', '', 'Франция', 'FR', 'passolution/countries/59/flag.png', 'passolution/countries/59/cover_image.jpg', '{\"w640\": \"passolution/countries/59/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/59/cover_image/1024w.jpg\"}', 'Europe', 'Paris', '66836154', '643801', '3427', 'Semi-presidential republic', NULL, 'EUR', '33', '12.3', '9.3', '81.8', 1, 'Visumpflichtige Personen benötigen ein Transitvisum.\r\nEs gelten folgende Ausnahmen: \r\nFür Reisende Staatsbürger der EU-Länder dürfen sich frei aufhalten. \r\nReisende der Staatsbürgerschaften Bulgarien, Kanada, Kroatien, Zypern, Irland, Japan, Rumänien und USA, die zu einem nicht Schengenland reisen oder von Bulgarien, Kanada, Kroatien, Zypern, Irland, Japan, Rumänien oder den USA zurückreisen mit Hinblick auf auf die Nationalitäten Afghanistan, Bangladesch, Dem. Rep. Kongo, Eritrea, Äthiopien, Ghana, Iran, Irak, Nigeria, Pakistan, Somalia und Sri Lanka dürfen sich maximal 24 Stunden im Transitbereich des Flughafens aufhalten.\r\nReisende der Nationalitäten Kamerun, Zentralafrikanische Republik, Tschad, Kongo, Elfenbeinküste, Dominikanische Republik, Guinea, Haiti, Indien, Mali, Mauretanien, Philippinen, Senegal, Sierra Leone, Südsudan, Sudan und Syrien dürfen sich maximal 24 Stunden im Transitbereich des Flughafens aufhalten.\r\nReisende mit der Staatsbürgerschaft Russland, die direkt von Armenien, Aserbaidschan, Belarus, Ägypten, Georgien, Moldawien, Türkei oder Ukraine einreisen benötigen ein Weiterreiseticket/ Weiterflugticket.', 'https://www.laenderdaten.info/Europa/Frankreich/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:35', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (60, 'Französisch-Guyana', 'Guyane française', 'French Guiana', 'Guyane française', 'Guyana Francese', 'Frans Guyana', 'Gujana Francuska', 'Guayana Francesa', 'Guiana Francesa', '', 'Французская Гвиана', 'GF', NULL, NULL, NULL, 'South America', 'Cayenne', '181000', '83534', '0', 'overseas territory of France', NULL, 'EUR', '594', '0', '0', '76.1', 1, 'Visumpflichtige Personen benötigen ein Transitvisum.Es gelten folgende Ausnahmen: Für Reisende Staatsbürger der EU-Länder dürfen sich frei aufhalten. Reisende der folgenden Staatsbürgerschaften : Afghanistan, Angola, Bangladesch, Dem. Rep. Kongo, Eritrea, Äthiopien, Ghana, Guyana, Haiti, Indien, Iran, Irak, Liberia, Libyen, Nigeria, Pakistan, Sierra Leone, Somalia, Sri Lanka, Sudan und Syrien mit einem diplomatischen Reisepass und Weiterreiseticket/ Weiterflugticket dürfen so lange warten bis der Anschlussflug abhebt, allerdings darf sich nur im vorherigen Flugzeug oder im Transitbereich des Flughafens aufgehalten werden. Visumpflichtige Personen benötigen ein Transitvisum.Es gelten folgende Ausnahmen: Für Reisende Staatsbürger der EU-Länder dürfen sich frei aufhalten. Reisende der folgenden Staatsbürgerschaften : Afghanistan, Angola, Bangladesch, Dem. Rep. Kongo, Eritrea, Äthiopien, Ghana, Guyana, Haiti, Indien, Iran, Irak, Liberia, Libyen, Nigeria, Pakistan, Sierra Leone, Somalia, Sri Lanka, Sudan und Syrien mit einem diplomatischen Reisepass und Weiterreiseticket/ Weiterflugticket dürfen so lange warten bis der Anschlussflug abhebt, allerdings darf sich nur im vorherigen Flugzeug oder im Transitbereich des Flughafens aufgehalten werden.', 'https://www.laenderdaten.info/Amerika/Franzoesisch-Guayana/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2026-02-18 12:46:20', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (61, 'Französisch-Polynesien', 'Polynésie française', 'French Polynesia', 'Polynésie française', 'Polinesia Francese', 'Frans Polynesië', 'Polinezja Francuska', 'Polinesia Francesa', 'Polinésia Francesa', '', 'Французская Полинезия', 'PF', NULL, 'passolution/countries/61/cover_image.jpg', '{\"w640\": \"passolution/countries/61/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/61/cover_image/1024w.jpg\"}', 'Oceania', 'Papeete', '285321', '4167', '2525', 'Parliamentary democracy (territory of France)', NULL, 'XPF', '689', '15', '5.1', '77.2', 1, 'Visumpflichtige Personen benötigen ein Transitvisum.Es gelten folgende Ausnahmen: Für Reisende Staatsbürger der EU-Länder dürfen sich frei aufhalten. Reisende anderer Staatsbürgerschaften mit einem Weiterreiseticket/ Weiterflugticket dürfen sich nur 3 Stunden im vorherigen Flugzeug oder im Transitbereich des Flughafens aufhalten.', 'https://www.laenderdaten.info/Ozeanien/Franzoesisch-Polynesien/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:35', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (62, 'Französische Süd- und Antarktisgebiete', 'Terres australes françaises', 'French Southern and Antarctic Lands', 'Terres australes françaises', 'Territori francesi del Sud e dell\'Antartico', 'Franse zuidelijke en Antarctische gebieden', 'Francuskie Terytoria Południowe i Antarktyczne', 'Territorios Australes y Antárticos Franceses', 'Territórios austrais e antárcticos franceses', '', 'Французские южные и антарктические территории', 'TF', NULL, NULL, NULL, 'Antarctica', 'Port-aux-Français', '0', '55', '2800', 'overseas territory of France', NULL, 'EUR', NULL, '0', '0', '0', 1, 'Visumpflichtige Personen benötigen ein Transitvisum.Es gelten folgende Ausnahmen: Für Reisende Staatsbürger der EU-Länder dürfen sich frei aufhalten.', 'https://www.laenderdaten.info/Antarktis/Franzoesische-Antarktis/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2023-12-13 13:26:33', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (63, 'Gabun', 'Le Gabon', 'Gabon', 'Le Gabon', 'Gabon', 'Gabon', 'Gabon', 'Gabón', 'Gabão', '', 'Габон', 'GA', 'passolution/countries/63/flag.png', 'passolution/countries/63/cover_image.jpg', '{\"w640\": \"passolution/countries/63/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/63/cover_image/1024w.jpg\"}', 'Africa', 'Libreville', '1738541', '267667', '885', 'Presidential republic', NULL, 'XAF', '241', '34.3', '13.1', '52.1', 1, 'Visumpflichtige Personen benötigen ein Transitvisum. Außer sie sind Staatsbürger folgender Länder, die mit dem selben Flugzeug oder dem nächsten Anschlussflug in ein Drittland weiterreisen, dürfen sich innerhalb von 24 Stunden ohne Visum im Transitbereich des Flughafens aufhalten:\r\nAlbanien, Armenien, Aserbaidschan, Berlarus, Bulgarien, China, Tschechien, Georgien, Ungarn, Kasachstan, Nordkorea, Kirgisistan, Moldawien, Mongolei, Montenegro, Polen, Rumänien, Russland, Serbien, Slowakei, Tadschikistan, Turkmenistan, Ukraine, Usbekistan, Vietnam.', 'https://www.laenderdaten.info/Afrika/Gabun/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:35', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (64, 'Gambia', 'The Gambia', 'Gambia', 'Gambie', 'Gambia', 'Gambia', 'Gambia', 'Gambia', 'Gâmbia', '', 'Гамбия', 'GM', 'passolution/countries/64/flag.png', 'passolution/countries/64/cover_image.jpg', '{\"w640\": \"passolution/countries/64/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/64/cover_image/1024w.jpg\"}', 'Africa', 'Banjul', '2009648', '11295', '80', 'Presidential republic', NULL, 'GMD', '220', '30.1', '7.1', '64.9', 1, 'Visumpflichtige Personen benötigen ein Transitvisum. Außer bei Weiterreise im gleichen Flugzeug und einem Aufenthalt von max. 2 Stunden. \r\nHinweis:\r\nInhaber einer palästinensischen ID-Card benötigen immer ein Visum.', 'https://www.laenderdaten.info/Afrika/Gambia/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:36', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (65, 'Georgien', 'Sakartvelo', 'Georgia', 'Géorgie', 'Georgia', 'Georgië', 'Gruzja', 'Georgia', 'Geórgia', '', 'Грузия', 'GE', 'passolution/countries/65/flag.png', 'passolution/countries/65/cover_image.jpg', '{\"w640\": \"passolution/countries/65/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/65/cover_image/1024w.jpg\"}', 'Asia', 'Tbilisi', '4928052', '69700', '310', 'Semi-presidential republic', NULL, 'GEL', '995', '12.5', '10.9', '76.2', 0, 'Bei gültigem Weiterreiseticket in ein Drittland wird für den Transitbereich im Flughafen kein Visum benötigt.', 'https://www.laenderdaten.info/Asien/Georgien/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:36', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (66, 'Ghana', 'Ghana', 'Ghana', 'Ghana', 'Ghana', 'Ghana', 'Ghana', 'Ghana', 'Gana', '', 'Гана', 'GH', 'passolution/countries/66/flag.png', 'passolution/countries/66/cover_image.jpg', '{\"w640\": \"passolution/countries/66/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/66/cover_image/1024w.jpg\"}', 'Africa', 'Accra', '26908262', '238533', '539', 'Presidential republic', NULL, 'GHS', '233', '30.8', '7.1', '66.6', 1, 'Visumpflichtige Personen benötigen ein Transitvisum. Es gelten folgende Ausnahmen: Reisende mit einem gültigen Ticket zur Weiterreise in ein Drittland können sich für 48 Stunden visumfrei im Transitbereich des Flughafens aufhalten.', 'https://www.laenderdaten.info/Afrika/Ghana/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:37', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (67, 'Gibraltar', 'Gibraltar', 'Gibraltar', 'Gibraltar', 'Gibilterra', 'Gibraltar', 'Gibraltar', 'Gibraltar', 'Gibraltar', '', 'Гибралтар', 'GI', 'passolution/countries/67/flag.png', 'passolution/countries/67/cover_image.jpg', '{\"w640\": \"passolution/countries/67/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/67/cover_image/1024w.jpg\"}', 'Europe', 'Gibraltar', '29328', '7', '12', 'Parliamentary democracy (self-governing territory of the UK)', NULL, 'GIP', '350', '14.1', '8.4', '79.4', 1, 'Visumpflichtige Personen benötigen ein Transitvisum. Es gelten folgende Ausnahmen: Reisende mit einem gültigen Weiterreiseticket in ein Drittland können sich für 24 Stunden visumfrei im Transitbereich des Flughafens aufhalten.', 'https://www.laenderdaten.info/Europa/Gibraltar/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:36', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (68, 'Grenada', 'Grenada', 'Grenada', 'Grenade', 'Grenada', 'Grenada', 'Grenada', 'Grenada', 'Granada', '', 'Гренада', 'GD', 'passolution/countries/68/flag.png', 'passolution/countries/68/cover_image.jpg', '{\"w640\": \"passolution/countries/68/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/68/cover_image/1024w.jpg\"}', 'North America', 'Saint George\'s', '111219', '344', '121', 'parliamentary democracy', NULL, 'XCD', '1809', '15.8', '8.1', '74.3', 0, 'Visumpflichtige Personen können sich mit gültigem Weiterreiseticket in ein Drittland ohne Transitvisum im Transitbereich des Flughafens aufhalten.', 'https://www.laenderdaten.info/Amerika/Grenada/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:38', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (69, 'Griechenland', 'Elláda', 'Greece', 'Grèce', 'Grecia', 'Griekenland', 'Grecja', 'Grecia', 'Grécia', '', 'Греция', 'GR', 'passolution/countries/69/flag.png', 'passolution/countries/69/cover_image.jpg', '{\"w640\": \"passolution/countries/69/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/69/cover_image/1024w.jpg\"}', 'Europe', 'Athens', '10773253', '131957', '13676', 'parliamentary republic', NULL, 'EUR', '30', '8.5', '11.2', '80.5', 1, 'Visumpflichtige Personen benötigen für den Aufenthalt im Transitbereich 24 Stunden kein Transitvisum. Es gelten folgende Ausnahmen: Staatsbürger der folgenden Nationen benötigen zum Aufenthalt im Transitbereich ein \"airport transit visa\": Afghanistan, Bangladesch, Kongo DR, Eritrea, Äthiopien, Ghana, Iran, Irak, Nigeria, Pakistan, Somalia, Sri Lanka.\r\nHinweis: Bei gültigem Visum oder einer Aufenthaltsgenehmigung für ein Schengen-Land, Andorra, Kanada, Japan, San Marino oder den USA oder bei Rückkehr aus diesen Ländern, wird kein Transitvisum benötigt.', 'https://www.laenderdaten.info/Europa/Griechenland/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:37', 28, '91.36.156.30', 1);
