INSERT INTO `webold_countries` VALUES (75, 'Guinea', 'Guinée', 'Guinea', 'Guinée', 'Guinea', 'Guinea', 'Gwinea', 'Guinea', 'Guiné', '', 'Гвинея', 'GN', 'passolution/countries/75/flag.png', 'passolution/countries/75/cover_image.jpg', '{\"w640\": \"passolution/countries/75/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/75/cover_image/1024w.jpg\"}', 'Africa', 'Conakry', '12093349', '245857', '320', 'Presidential republic', NULL, 'GNF', '224', '35.4', '9.2', '60.6', 1, 'Visumpflichtige Personen benötigen ein Transitvisum. Es gelten folgende Ausnahmen: Reisende mit einem Weiterreiseticket in ein Drittland können sich 24 Stunden ohne Visum im Transitbereich des Flughafens aufhalten.', 'https://www.laenderdaten.info/Afrika/Guinea/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:39', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (76, 'Guinea-Bissau', 'Guiné-Bissau', 'Guinea-Bissau', 'Guinée-Bissau', 'Guinea-Bissau', 'Guinee-Bissau', 'Gwinea Bissau', 'Guinea-Bissau', 'Guiné-Bissau', '', 'Гвинея-Бисау', 'GW', 'passolution/countries/76/flag.png', 'passolution/countries/76/cover_image.jpg', '{\"w640\": \"passolution/countries/76/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/76/cover_image/1024w.jpg\"}', 'Africa', 'Bissau', '1759159', '36125', '350', 'Semi-presidential republic', NULL, 'XOF', '245', '32.9', '14.1', '50.6', 0, 'Visumpflichtige Personen mit einem Weiterreiseticket in ein Drittland können sich ohne Visum im Transitbereich des Flughafens aufhalten.', 'https://www.laenderdaten.info/Afrika/Guinea-Bissau/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:39', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (77, 'Guyana', 'Guyana', 'Guyana', 'Guyane', 'Guyana', 'Guyana', 'Gujana', 'Guayana', 'Guiana', '', 'Гайана', 'GY', 'passolution/countries/77/flag.png', 'passolution/countries/77/cover_image.jpg', '{\"w640\": \"passolution/countries/77/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/77/cover_image/1024w.jpg\"}', 'South America', 'Georgetown', '735909', '214969', '459', 'parliamentary republic', NULL, 'GYD', '592', '15.5', '7.4', '68.4', 1, 'Visumpflichtige Personen benötigen ein Transitvisum. Es gelten folgende Ausnahmen: Reisende mit einem Weiterflugticket für ein Drittland, die mit dem selben Flugzeug weiterreisen oder sich maximal 7 Stunden im Transitbereich aufhalten, benötigen kein Transitvisum.\r\nHinweis: Diese Ausnahmen gelten nicht für folgende Nationalitäten: Armenien, Aserbaidschan, Belarus, Bulgarien, China, Kuba, Tschechien, Georgien, Ungarn, Kasachstan, Kirgisistan, Moldawien, Mongolei, Montenegro, Polen, Rumänien, Serbien, Slowakei, Tadschikistan, Turkmenistan, Ukraine, Usbekistan, Vietnam.', 'https://www.laenderdaten.info/Amerika/Guyana/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:38', 28, '91.36.156.30', 1);
