INSERT INTO `webold_countries` VALUES (80, 'Honduras', 'Honduras', 'Honduras', 'Honduras', 'Honduras', 'Honduras', 'Honduras', 'Honduras', 'Honduras', '', 'Гондурас', 'HN', 'passolution/countries/80/flag.png', 'passolution/countries/80/cover_image.jpg', '{\"w640\": \"passolution/countries/80/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/80/cover_image/1024w.jpg\"}', 'Central America', 'Tegucigalpa', '8893259', '112090', '669', 'Presidential republic', NULL, 'HNL', '504', '22.8', '5.2', '71.1', 1, 'Visumpflichtige Personen benötigen ein Transitvisum. Es gelten folgende Ausnahmen: Reisende mit gültigem Weiterreiseticket in ein Drittland für den selben Tag können sich ohne Transitvisum im Transitbereich des Flughafens aufhalten.', 'https://www.laenderdaten.info/Amerika/Honduras/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:40', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (81, 'Hongkong', 'Xianggang/Hong Kong', 'Hong Kong', 'Hong Kong', 'Hong Kong', 'Hong Kong', 'Hongkong', 'Hong Kong', 'Hong Kong', '', 'Гонконг', 'HK', 'passolution/countries/81/flag.png', 'passolution/countries/81/cover_image.jpg', '{\"w640\": \"passolution/countries/81/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/81/cover_image/1024w.jpg\"}', 'Asia', 'Hong Kong', '7167403', '1108', '733', 'Presidential limited democracy (special administrative region of China)', NULL, 'HKD', '852', '9.1', '7.2', '82.9', 1, 'Visumpflichtige Personen benötigen ein Transitvisum.\r\nEs gelten folgende Ausnahmen: Chinesische Staatsbürger, die aus einem Drittland nach China oder Macau (und umgekehrt), mit einem gültigen Weiterreiseticket einreisen wollen, können sich bis zu 7 Tage visumfrei im Transitbereich des Flughafens aufhalten. Andere Staatsbürger können sich unter den gleichen Bedingungen für 48 Stunden dort aufhalten. \r\nHinweis: Folgende Nationalitäten benötigen immer ein Transitvisum: Afghanistan, Zentralafrikanische Republik, Kongo DR, Elfenbeinküste, Eritrea, Gambia, Guinea-Bissau, Iran, Irak, Nordkorea, Liberia, Libyen, Nepal, Nigeria, Pakistan, Ruanda, Sierra Leone, Somalia, Südsudan, Sudan, Jemen, Angola, Bangladesch, Burundi, Kamerun, Kongo, Äthiopien, Ghana, Sri Lanka, Togo.', 'https://www.laenderdaten.info/Asien/Hongkong/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:40', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (82, 'Indien', 'Bharat/India', 'India', 'Inde', 'India', 'India', 'Indie', 'India', 'Índia', '', 'Индия', 'IN', 'passolution/countries/82/flag.png', 'passolution/countries/82/cover_image.jpg', '{\"w640\": \"passolution/countries/82/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/82/cover_image/1024w.jpg\"}', 'Asia', 'New Delhi', '1266883598', '3287263', '7000', 'Federal parliamentary republic', NULL, 'INR', '91', '19.3', '7.3', '68.5', 1, 'Visumpflichtige Personen benötigen ein Transitvisum. Es gelten folgende Ausnahmen: Reisende, die ein gültiges Weiterreiseticket besitzen, können sich für 24 Stunden ohne Transitvisum im Transitbereich des Flughafens aufhalten.', 'https://www.laenderdaten.info/Asien/Indien/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:39', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (83, 'Indonesien', 'Indonesia', 'Indonesia', 'Indonésie', 'Indonesia', 'Indonesië', 'Indonezja', 'Indonesia', 'Indonésia', '', 'ИндонезияIndonésie', 'ID', 'passolution/countries/83/flag.png', 'passolution/countries/83/cover_image.jpg', '{\"w640\": \"passolution/countries/83/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/83/cover_image/1024w.jpg\"}', 'Asia', 'Jakarta', '258316051', '1904569', '54716', 'Presidential republic', NULL, 'IDR', '62', '16.4', '6.4', '72.7', 1, 'Visumpflichtige Personen benötigen ein Transitvisum. Es gelten folgende Ausnahmen: Reisende mit einem gültigen Weiterreiseticket in ein Drittland können sich für 8 Stunden ohne Transitvisum im Transitbereich des Flughafens aufhalten (24 Stunden in Jakarta). Der Transit über verschiedene Terminals muss vorher arrangiert werden. Hinweis: In Denpasar-Bali (DPS) gelten die normalen Visabedingungen für Indonesien.', 'https://www.laenderdaten.info/Asien/Indonesien/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:40', 28, '91.36.156.30', 1);
