INSERT INTO `webold_countries` VALUES (85, 'Irak', 'Al-´Iraq', 'Iraq', 'Irak', 'Iraq', 'Irak', 'Irak', 'Iraq', 'Iraque', '', 'Ирак', 'IQ', 'passolution/countries/85/flag.png', 'passolution/countries/85/cover_image.jpg', '{\"w640\": \"passolution/countries/85/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/85/cover_image/1024w.jpg\"}', 'Asia', 'Baghdad', '38146025', '438317', '58', 'Federal parliamentary republic', NULL, 'IQD', '964', '30.9', '3.8', '74.9', 0, 'Es gelten die normalen Visabedingungen für den Irak.', 'https://www.laenderdaten.info/Asien/Irak/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:40', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (86, 'Iran', 'Iran', 'Iran', 'Iran', 'Iran', 'Iran', 'Iran', 'Irán', 'Irão', '', 'Иран', 'IR', 'passolution/countries/86/flag.png', 'passolution/countries/86/cover_image.jpg', '{\"w640\": \"passolution/countries/86/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/86/cover_image/1024w.jpg\"}', 'Asia', 'Tehran', '82801633', '1648195', '2440', 'islamic republic', NULL, 'IRR', '98', '17.8', '5.9', '71.4', 1, 'Visumpflichtige Personen benötigen ein Transitvisum. Es gelten folgende Ausnahmen: Reisende mit gültigem Weiterreiseticket für ein Drittland können sich ohne Transitvisum für 24 Stunden im Transitbereich des Flughafens aufhalten (für Jemen 8 Stunden).', 'https://www.laenderdaten.info/Asien/Iran/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:40', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (87, 'Irland', 'Ireland/Éire', 'Ireland', 'Irlande', 'Irlanda', 'Ierland', 'Irlandia', 'Irlanda', 'Irlanda', '', 'Ирландия', 'IE', 'passolution/countries/87/flag.png', 'passolution/countries/87/cover_image.jpg', '{\"w640\": \"passolution/countries/87/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/87/cover_image/1024w.jpg\"}', 'Europe', 'Dublin', '4952473', '70273', '1448', 'parliamentary republic', NULL, 'EUR', '353', '14.5', '6.5', '80.8', 1, 'Visumpflichtige Personen benötigen ein Transitvisum. Es gelten folgende Ausnahmen: Reisende mit gültigem Weiterreiseticket für den selben Tag können sich ohne Transitvisum im Transitbereich des Flughafens aufhalten. Von dieser Regel ausgenommen sind folgende Staatsbürger: Afghanistan, Albanien, Kongo DR, Kuba, Eritrea, Äthiopien, Georgien, Ghana, Iran, Irak, Libanon, Moldawien, Nigeria, Somalia, Sri Lanka, Ukraine, Simbabwe.', 'https://www.laenderdaten.info/Europa/Irland/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:41', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (88, 'Island', 'Ísland', 'Iceland', 'Islande', 'Islanda', 'IJsland', 'Islandia', 'Islandia', 'Islândia', '', 'Исландия', 'IS', 'passolution/countries/88/flag.png', 'passolution/countries/88/cover_image.jpg', '{\"w640\": \"passolution/countries/88/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/88/cover_image/1024w.jpg\"}', 'Europe', 'Reykjavík', '335878', '103000', '4970', 'parliamentary republic', NULL, 'ISK', '354', '13.8', '6.3', '83', 1, 'Visumpflichtige Personen benötigen ein Transitvisum. \r\nEs gelten folgende Ausnahmen: Reisende, die aus einem Nicht-Schengen Staat einreisen und ein gültiges Weiterreiseticket in ein anderes Nicht-Schengen Land besitzen, können sich ohne Transitvisum im Transitbereich des Flughafens aufhalten. Folgende Staatsbürger, die aus Bulgarien, Kanada, Kroatien, Zypern, Irland, Japan, Rumänien, USA oder Vereinigtes Königreich zurückkehren und dort ein Visum hatten oder eine Aufenthaltsgenehmigung für Andorra, Bulgarien, Kanada, Kroatien, Zypern, Irland, Japan, Rumänien, San Marino, USA oder Vereinigtes Königreich besitzen und noch am selben Tag weiterreisen, können sich ohne Transitvisum im Transitbereich des Flughafens aufhalten: Afghanistan, Bangladesch, Kongo DR, Eritrea, Äthiopien, Ghana, Iran, Irak, Nigeria, Pakistan, Somalia, Sri Lanka.', 'https://www.laenderdaten.info/Europa/Island/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:40', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (89, 'Israel', 'Yisra’el/Isra’il', 'Israel', 'Israël', 'Israele', 'Israël', 'Izrael', 'Israel', 'Israel', '', 'Израиль', 'IL', 'passolution/countries/89/flag.png', 'passolution/countries/89/cover_image.jpg', '{\"w640\": \"passolution/countries/89/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/89/cover_image/1024w.jpg\"}', 'Asia', 'Jerusalem', '8174527', '20770', '273', 'parliamentary democracy', NULL, 'ILS', '972', '18.3', '5.2', '82.4', 1, 'Visumpflichtige Personen benötigen ein Transitvisum. Es gelten folgende Ausnahmen: Reisende mit einem gültigen Weiterreiseticket in ein Drittland können sich für 24 Stunden ohne Transitvisum im Transitbereich des Flughafens aufhalten.', 'https://www.laenderdaten.info/Asien/Israel/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:41', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (90, 'Italien', 'Italia', 'Italy', 'Italie', 'Italia', 'Italie', 'Włochy', 'Italia', 'Itália', '', 'Италия', 'IT', 'passolution/countries/90/flag.png', 'passolution/countries/90/cover_image.jpg', '{\"w640\": \"passolution/countries/90/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/90/cover_image/1024w.jpg\"}', 'Europe', 'Rome', '62007540', '301340', '7600', 'parliamentary republic', NULL, 'EUR', '39', '8.7', '10.3', '82.2', 1, 'Visumpflichtige Personen benötigen ein Transitvisum. Es gelten folgende Ausnahmen: Reisende, die aus einem Nicht-Schengen Staat einreisen und ein gültiges Weiterreiseticket in ein anderes Nicht-Schengen Land besitzen, können sich für 48 Stunden ohne Transitvisum im Transitbereich des Flughafens aufhalten. Folgende Staatsbürger, die aus Bulgarien, Kanada, Kroatien, Zypern, Irland, Japan, Rumänien, USA oder Vereinigtes Königreich zurückkehren und dort ein Visum hatten und innerhalb von 24 Stunden weiterreisen, oder eine Aufenthaltsgenehmigung für Andorra, Bulgarien, Kanada, Kroatien, Zypern, Irland, Japan, Rumänien, San Marino, USA oder Vereinigtes Königreich besitzen und innerhalb von 48 Stunden weiterreisen, können sich ohne Transitvisum im Transitbereich des Flughafens aufhalten: Afghanistan, Bangladesch, Kongo DR, Eritrea, Äthiopien, Ghana, Iran, Irak, Nigeria, Pakistan, Somalia, Sri Lanka, Syrien. \r\nHinweis: Dies gilt nur für die Flughäfen Mailand (MXP), Rom (FCO) und Venedig (VCE).', 'https://www.laenderdaten.info/Europa/Italien/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:42', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (91, 'Jamaika', 'Jamaica', 'Jamaica', 'Jamaïque', 'Giamaica', 'Jamaica', 'Jamajka', 'Jamaica', 'Jamaica', '', 'Ямайка', 'JM', 'passolution/countries/91/flag.png', 'passolution/countries/91/cover_image.jpg', '{\"w640\": \"passolution/countries/91/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/91/cover_image/1024w.jpg\"}', 'North America', 'Kingston', '2970340', '10991', '1022', 'Parliamentary democracy (under constitutional monarchy)', NULL, 'JMD', '1876', '18', '6.7', '73.6', 1, 'Visumpflichtige Personen benötigen ein Transitvisum. Es gelten folgende Ausnahmen: Reisende mit einem gültigen Ticket für die Weiterreise in ein Drittland innerhalb von 72 Stunden, benötigen für den Aufenthalt im Transitbereich des Flughafens kein Transitvisum. Staatsbürger der folgenden Nationen, die ein gültiges Ticket für die Weiterreise besitzen und im Zielland wohnen, können sich ohne Transitvisum für 3 Tage im Transitbereich des Flughafens aufhalten: Afghanistan, Nordkorea, Mongolei, Vietnam.', 'https://www.laenderdaten.info/Amerika/Jamaika/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:43', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (92, 'Japan', 'Nihon/Nippon', 'Japan', 'Japon', 'Giappone', 'Japan', 'Japonia', 'Japón', 'Japão', '', 'Япония', 'JP', 'passolution/countries/92/flag.png', 'passolution/countries/92/cover_image.jpg', '{\"w640\": \"passolution/countries/92/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/92/cover_image/1024w.jpg\"}', 'Asia', 'Tokyo', '126702133', '377915', '29751', 'Parliamentary constitutional monarchy', NULL, 'JPY', '81', '7.8', '9.6', '85', 1, 'Visumpflichtige Personen benötigen ein Transitvisum. Es gelten folgende Ausnahmen: Reisende, die ein gültiges Weiterreiseticket für denselben Tag (beim Transit über Tokio (HND) oder Osaka (KIX): 72 Stunden), in ein Drittland besitzen, benötigen kein Transitvisum für den Transitbereich des Flughafens.\r\nIst kein Anschlussflug am selben Tag verfügbar, kann ein \"Shore Pass\" für 72h bei Ankunft erworben werden. Dafür müssen alle nötigen Dokumente für die Einreise ins Zielland, sowie aureichend finanzielle Mittel für den Aufenthalt nachgewiesen werden. Außerdem muss die Ankunft und Abreise über Flughäfen bzw. Häfen erfolgen, die der selben unten genannten Gruppe angehören: \r\n-Gruppe A: Flughäfen: NRT,HND,NGO,KIJ, KMQ,OKO. Häfen: Tokio, Yokohama, Niigata, Nagoya\r\n-Gruppe B: Flughäfen: KIX,NGO,KMQ. Häfen: Osaka, Kobe, Nagoya.\r\n-Gruppe C: Flughäfen: FUK,NGS,KMJ,KOJ,OKA,DNA. Häfen: Hakata (Fukuoka), Shimonoseki, Naha (Okinawa) \r\n-Gruppe D: Flughäfen: CTS. Häfen: Tomakomai, Otaru, Hakodate, Muroran', 'https://www.laenderdaten.info/Asien/Japan/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:41', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (93, 'Jemen', 'Al-Yaman', 'Yemen', 'Yémen', 'Yemen', 'Jemen', 'Jemen', 'Yemen', 'Iêmen', '', 'Йемен', 'YE', 'passolution/countries/93/flag.png', 'passolution/countries/93/cover_image.jpg', '{\"w640\": \"passolution/countries/93/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/93/cover_image/1024w.jpg\"}', 'Asia', 'Sanaa', '27392779', '527968', '1906', 'republic', NULL, 'YER', '967', '29.2', '6.1', '65.5', 1, 'Visumpflichtige Personen benötigen ein Transitvisum. Es gelten folgende Ausnahmen: Reisende mit einem gültigen Weiterflugticket in ein Drittland können sich für 24 Stunden ohne Transitvisum im Transitbereich des Flughafens aufhalten. Reisende, die mit Yemenia Yemen Airways ein- und ausreisen, können sich 96 Stunden ohne Transitvisum im Transitbereich des Flughafens aufhalten.', 'https://www.laenderdaten.info/Asien/Jemen/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:41', 28, '91.36.156.30', 1);
