INSERT INTO `webold_countries` VALUES (95, 'Jordanien', 'Al-Urdunn', 'Jordan', 'Jordanie', 'Giordania', 'Jordanië', 'Jordania', 'Jordania', 'Jordânia', '', 'Иордания', 'JO', 'passolution/countries/95/flag.png', 'passolution/countries/95/cover_image.jpg', '{\"w640\": \"passolution/countries/95/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/95/cover_image/1024w.jpg\"}', 'Asia', 'Amman', '8185384', '89342', '26', 'Parliamentary constitutional monarchy', NULL, 'JOD', '962', '25.5', '3.8', '74.6', 1, 'Visumpflichtige Personen benötigen ein Transitvisum.Es gelten folgende Ausnahmen: Reisende mit einem gültigen Weiterreiseticket in ein Drittland können sich für 48 Stunden ohne Transitvisum im Transitbereich des Flughafens aufhalten.', 'https://www.laenderdaten.info/Asien/Jordanien/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:44', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (96, 'Jungferninseln (UK)', 'British Virgin Islands', 'British Virgin Islands', 'Îles Vierges britanniques', 'Isole Vergini britanniche', 'Britse Maagdeneilanden', 'Brytyjskie Wyspy Dziewicze', 'Islas Vírgenes Británicas', 'Ilhas Virgens Britânicas', '', 'Британские Виргинские острова', 'VG', NULL, 'passolution/countries/96/cover_image.jpg', '{\"w640\": \"passolution/countries/96/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/96/cover_image/1024w.jpg\"}', 'North America', 'Road Town', '34232', '151', '80', 'Parliamentary democracy (self-governing territory of the UK)', NULL, 'USD', '1-284', '11', '5.1', '78.6', 1, 'Visumpflichtige Personen benötigen ein Transitvisum. Es gelten folgende Ausnahmen: Reisende, die ein gültiges Weiterreiseticket in ein Drittland besitzen, können sich für 24 Stunden ohne Transitvisum im Transitbereich des Flughafens aufhalten.', 'https://www.laenderdaten.info/Amerika/Jungferninseln-UK/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:42', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (97, 'Jungferninseln (US)', 'Virgin Islands of the United States', 'Virgin Islands', 'Vierges américaines (Îles)', 'Isole Vergini Americane', 'Amerikaanse Maagdeneilanden', 'Amerykańskie Wyspy Dziewicze', 'Islas Vírgenes Americanas', 'Ilhas Virgens Americanas', '', 'Американские Виргинские острова', 'VI', 'passolution/countries/97/flag.png', 'passolution/countries/97/cover_image.jpg', '{\"w640\": \"passolution/countries/97/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/97/cover_image/1024w.jpg\"}', 'North America', 'Charlotte Amalie', '102951', '1910', '188', 'Presidential democracy (self-governing territory of the US)', NULL, 'USD', '1809', '10.2', '8.9', '80', 0, 'Es gelten die normalen Visa- und Einreisebedingungen für die USA.', 'https://www.laenderdaten.info/Amerika/Jungferninseln-US/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:42', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (98, 'Kaimaninseln', 'Cayman Islands', 'Cayman Islands', 'Îles Caïmans', 'Isole Cayman', 'Kaaiman Eilanden', 'Kajmany', 'Islas Caimán', 'Ilhas Caimão', '', 'Каймановы острова', 'KY', NULL, 'passolution/countries/98/cover_image.jpg', '{\"w640\": \"passolution/countries/98/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/98/cover_image/1024w.jpg\"}', 'North America', 'George Town', '57268', '264', '160', 'Parliamentary democracy (self-governing territory of the UK)', NULL, 'KYD', '1809', '12.1', '5.7', '81.2', 1, 'Visumpflichtige Personen benötigen ein Transitvisum. Es gelten folgende Ausnahmen: Reisende, die ein gültiges Weiterreiseticket in ein Drittland besitzen, können sich ohne Transitvisum für 24 Stunden im Transitbereich des Flughafens aufhalten. Hiervon ausgenommen sind Staatsbürger folgender Nationen: Algerien, Angola, Bangladesch, Berlarus, Bulgaria, Burundi, Kamerun, China, Kolumbien, Kongo DR, Elfenbeinküste, Eritrea, Äthiopien, Gambia, Ghana, Indien, Iran, Irak, Libanon, Liberia, Mazedonien, Moldawien, Montenegro, Myanmar, Nepal, Nigeria, Pakistan, Rumänienn, Ruanda, Saudi Arabien, Senegal, Serbien, Sierra Leone, Somalia, Sri LAnka, Sudan, Syrien, Türkei, Uganda, Vietnam, Simbabwe, Palästina (Inhaber einer palästinensischen ID Card).', 'https://www.laenderdaten.info/Amerika/Kaimaninseln/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:42', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (99, 'Kambodscha', 'Kâmpuchéa', 'Cambodia', 'Cambodge', 'Cambogia', 'Cambodja', 'Kambodża', 'Camboya', 'Camboja', '', 'Камбоджа', 'KH', 'passolution/countries/99/flag.png', 'passolution/countries/99/cover_image.jpg', '{\"w640\": \"passolution/countries/99/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/99/cover_image/1024w.jpg\"}', 'Asia', 'Phnom Penh', '15957223', '181035', '443', 'Parliamentary constitutional monarchy', NULL, 'KHR', '855', '23.4', '7.6', '64.5', 1, 'Visumpflichtige Personen benötigen ein Transitvisum. Es gelten folgende Ausnahmen: Reisende, die ein gültiges Weiterflugticket besitzen und über Phnom Penh im selben Flugzeug ein- und ausreisen und Dokumente für die nächste Destination mit sich haben, benötigen kein Transitvisum für den Aufenthalt im Transitbereich des Flughafens.', 'https://www.laenderdaten.info/Asien/Kambodscha/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:45', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (100, 'Kamerun', 'Cameroun/Cameroon', 'Cameroon', 'Cameroun', 'Camerun', 'Kameroen', 'Kamerun', 'Camerún', 'Camarões', '', 'Камерун', 'CM', 'passolution/countries/100/flag.png', 'passolution/countries/100/cover_image.jpg', '{\"w640\": \"passolution/countries/100/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/100/cover_image/1024w.jpg\"}', 'Africa', 'Yaoundé', '24360803', '475440', '402', 'Presidential republic', NULL, 'XAF', '237', '35.8', '9.8', '58.5', 1, 'Visumpflichtige Personen benötigen ein Transitvisum. Es gelten folgende Ausnahmen: Reisende, die ein gültiges Weiterreiseticket in ein Drittland besitzen, dürfen sich für 24 Stunden (Flughafen Yaounde) bzw. 48 Stunden (Douala) ohne Transitvisum im Transitbereich des Flughafens aufhalten. Hinweis: Dies gilt nicht, wenn die genutzte Airline auch Direktflüge anbietet.', 'https://www.laenderdaten.info/Afrika/Kamerun/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:43', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (101, 'Kanada', 'Canada', 'Canada', 'Canada', 'Canada', 'Canada', 'Kanada', 'Canadá', 'Canadá', '', 'Канада', 'CA', 'passolution/countries/101/flag.png', 'passolution/countries/101/cover_image.jpg', '{\"w640\": \"passolution/countries/101/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/101/cover_image/1024w.jpg\"}', 'North America', 'Ottawa', '35362905', '9984670', '202080', 'Federal parliamentary republic (under constitutional monarchy)', NULL, 'CAD', '1', '10.3', '8.5', '81.9', 1, 'Visumpflichtige Personen benötigen ein Transitvisum. Es gelten folgende Ausnahmen: Staatsbürger von Indonesien, Philippinen, Thailand, China und Taiwan (nur mit Pass OHNE ID-Nummer), können sich ohne Transitvisum im Transitbereich des Flughafens aufhalten, wenn sie: 1.) ein gültiges Weiterreiseticket für den selben Kalendertag besitzen und 2.) In die USA einreisen oder aus den USA in ein Drittland reisen und bei Einreise in die USA ein gültiges US-Visum (inklusive aller nötigen Unterlagen) besitzen bzw. bei Ausreise aus den USA  ein Visum, das mindestens bis zum Ausreisetag gültig war. Des weiteren werden alle nötigen Dokumente für die Einreise in das Zielland benötigt. \r\nDer visumfreie Transit ist nur an folgenden Flughäfen und zu folgenden Bedingungen möglich:\r\n1) Calgary (YYC) zwischen 4:30 und 20:00 Uhr mit folgenden Airlines: Air Canada (AC), Air Canada\r\n  Rouge (RV), Air Georgian (ZX), Hainan Airlines (HU), Sky\r\n  Regional (RS) oder WestJet (WS).\r\n2) Toronto (YYZ) zwischen 4:30 und 21:00 Uhr mit folgenden Airlines: Air Canada (AC), Air Canada Rouge (RV), Air Georgian (ZX), Jazz Air (QK) oder Sky Regional (RS).\r\n3) Vancouver (YVR) zwischen 4:30 und 20:30 mit folgenden Airlines:   Air Canada (AC), Air Canada Rouge (RV), Air China (CA),\r\n  Cathay Pacific (CX), China Airlines (CI), China Southern\r\n  (CZ), Jazz Air (QK), Philippine Airlines (PR), Sky Regional\r\n  (RS) or WestJet (WS). \r\n\r\nHinweis: Chinesische Staatsbürger müssen von folgenden Flughäfen aus nach Kanada einreisen:  Beijing (PEK), Chengdu (CTU), Fuzhou (FOC),\r\n  Guangzhou (CAN), Harbin (HRB), Hong Kong (HKG), Manila\r\n  (MNL), Nagoya (NGO), Osaka (ITM), Seoul (ICN), Shanghai\r\n  (SHA), Shanghai (PVG), Shenyang (SHE), Taipei (TPE), Tokyo\r\n  (HND), Tokyo (NRT) oder Xiamen (XMN).', 'https://www.laenderdaten.info/Amerika/Kanada/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:45', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (102, 'Kap Verde', 'Cabo Verde', 'Cape Verde', 'Cap-Vert', 'Capo Verde', 'Kaapverdië', 'Wyspy Zielonego Przylądka', 'Cabo Verde', 'Cabo Verde', '', 'Кабо-Верде', 'CV', 'passolution/countries/102/flag.png', 'passolution/countries/102/cover_image.jpg', '{\"w640\": \"passolution/countries/102/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/102/cover_image/1024w.jpg\"}', 'Africa', 'Praia', '553432', '4033', '965', 'parliamentary republic', NULL, 'CVE', '238', '20.2', '6.1', '72.1', 1, 'Visumpflichtige Personen benötigen ein Transitvisum. Es gelten folgende Ausnahmen: Reisende, die ein gültiges Weiterreiseticket in ein Drittland besiten können sich ohne Transitvisum im Transitbereich des Flughafens aufhalten.', 'https://www.laenderdaten.info/Afrika/Kap-Verde/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:43', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (103, 'Kasachstan', 'Qazaqstan', 'Kazakhstan', 'Kazakhstan', 'Kazakistan', 'Kazachstan', 'Kazachstan', 'Kazajstán', 'Cazaquistão', '', 'Казахстан', 'KZ', 'passolution/countries/103/flag.png', 'passolution/countries/103/cover_image.jpg', '{\"w640\": \"passolution/countries/103/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/103/cover_image/1024w.jpg\"}', 'Asia', 'Astana', '18360353', '2724900', '0', 'Presidential republic', NULL, 'KZT', '7', '18.7', '8.2', '70.8', 1, 'Visumpflichtige Personen benötigen ein Transitvisum. Es gelten folgende Ausnahmen: Reisende, die mit einem gültigen Weiterreiseticket über Almaty (ALA) oder Astana (TSE) innerhalb von 24 Stunden in ein Drittland weiterreisen, benötigen für den Aufenthalt im Transitbereich des Flughafens kein Visum. Benötigt werden alle nötigen Dokumente zur Einreise in das Zielland.', 'https://www.laenderdaten.info/Asien/Kasachstan/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:43', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (104, 'Katar', 'Qatar', 'Qatar', 'Qatar', 'Qatar', 'Qatar', 'atar', 'Qatar', 'Qatar', '', 'Катар', 'QA', 'passolution/countries/104/flag.png', 'passolution/countries/104/cover_image.jpg', '{\"w640\": \"passolution/countries/104/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/104/cover_image/1024w.jpg\"}', 'Asia', 'Doha', '2258283', '11586', '563', 'absolute monarchy', NULL, 'QAR', '974', '9.7', '1.5', '78.7', 1, 'Visumpflichtige Personen benötigen ein Transitvisum. Es gelten folgende Ausnahmen: Reisende, die ein gültiges Weiterreiseticket in ein Drittland besitzen und innerhalb von 24 Stunden weiterreisen, dürfen sich ohne Visum im Transitbereich des Flughafens aufhalten.  Benötigt werden alle nötigen Dokumente zur Einreise in das Zielland. \r\nHinweis: Reisende, die im Vorfeld einen Aufenthalt arrangieren, sog. \"Stopover Paid by Carrier\" (STPC) , können mit einem mindestens 3 Monate gültigen Reisepass den Flughafen verlassen.', 'https://www.laenderdaten.info/Asien/Katar/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:43', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (105, 'Kenia', 'Kenya', 'Kenya', 'Kenya', 'Kenya', 'Kenia', 'Kenia', 'Kenia', 'Quênia', '', 'Кения', 'KE', 'passolution/countries/105/flag.png', 'passolution/countries/105/cover_image.jpg', '{\"w640\": \"passolution/countries/105/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/105/cover_image/1024w.jpg\"}', 'Africa', 'Nairobi', '46790758', '580367', '536', 'Presidential republic', NULL, 'KES', '254', '25.1', '6.8', '64', 1, 'Visumpflichtige Personen benötigen ein Transitvisum. Es gelten folgende Ausnahmen: Reisende, die ein gültiges Weiterreiseticket besitzen und innerhalb von 24 Stunden in ein Drittland weiterreisen, benötigen für den Aufenthalt im  Transitbereich des Flughafens kein Visum. Benötigt werden alle nötigen Dokumente zur Einreise in das Zielland.', 'https://www.laenderdaten.info/Afrika/Kenia/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:44', 28, '91.36.156.30', 1);
