INSERT INTO `webold_countries` VALUES (109, 'Kolumbien', 'Colombia', 'Colombia', 'Colombie', 'Colombia', 'Colombia', 'Kolumbia', 'Colombia', 'Colômbia', '', 'Колумбия', 'CO', 'passolution/countries/109/flag.png', 'passolution/countries/109/cover_image.jpg', '{\"w640\": \"passolution/countries/109/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/109/cover_image/1024w.jpg\"}', 'South America', 'Bogotá', '47220856', '1138910', '3208', 'Presidential republic', NULL, 'COP', '57', '16.3', '5.4', '75.7', 1, 'Visumpflichtige Personen benötigen ein Transitvisum. Es gelten folgende Ausnahmen: Reisende, die ein gültiges Weiterreiseticket in ein Drittland besitzen und innerhalb von 24 Stunden weiterreisen, benötigen für den Aufenthalt im Transitbereich des Flughafens kein Visum. Benötigt werden alle nötigen Dokumente zur Einreise in das Zielland.\r\nStaatsbürger von Kuba und Personen mit palästinensischer ID-Card benötigen immer ein Visum.', 'https://www.laenderdaten.info/Amerika/Kolumbien/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:44', 28, '91.36.156.30', 1);
