INSERT INTO `webold_countries` VALUES (113, 'Kroatien', 'Hrvatska', 'Croatia', 'Croatie', 'Croazia', 'Kroatië', 'Chorwacja', 'Croacia', 'Croácia', '', 'Хорватия', 'HR', 'passolution/countries/113/flag.png', 'passolution/countries/113/cover_image.jpg', '{\"w640\": \"passolution/countries/113/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/113/cover_image/1024w.jpg\"}', 'Europe', 'Zagreb', '4313707', '56594', '5835', 'parliamentary republic', NULL, 'HRK', '385', '9', '12.1', '75.9', 1, 'Visumpflichtige Personen benötigen ein Transitvisum. Es gelten folgende Ausnahmen: Reisende, die über Zagreb (ZAG) aus einem Nicht-Schengen Staat einreisen und ein gültiges Weiterreiseticket in ein anderes Nicht-Schengen Land besitzen, können sich ohne Transitvisum im Transitbereich des Flughafens aufhalten. Folgende Staatsbürger, die aus Bulgarien, Kanada, Zypern, Irland, Japan, Rumänien, USA oder Vereinigtes Königreich zurückkehren und dort ein Visum hatten oder eine Aufenthaltsgenehmigung für Andorra, Bulgarien, Kanada, Zypern, Irland, Japan, Rumänien, San Marino, USA oder Vereinigtes Königreich besitzen und noch am selben Tag weiterreisen, können sich ohne Transitvisum im Transitbereich des Flughafens aufhalten: Afghanistan, Bangladesch, Kongo DR, Eritrea, Äthiopien, Ghana, Iran, Irak, Nigeria, Pakistan, Somalia, Sri Lanka.', 'https://www.laenderdaten.info/Europa/Kroatien/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:09:45', 28, '91.36.156.30', 1);
