INSERT INTO `webold_countries` VALUES (187, 'Sankt Bartholomäus', 'Saint-Barthélemy', 'Saint Barthelemy', 'Saint-Barthélemy', 'San Bartolomeo', 'Sint-Bartholomeus', 'Święty Bartłomiej', 'San Bartolomé', 'São Bartolomeu', '', 'Святой Варфоломей', 'BL', NULL, NULL, NULL, 'America', 'Gustavia', '7209', '21', '0', 'territory of France', NULL, 'EUR', '590', '0', '0', '0', 0, 'Visumfrei bei einem Aufenthalt von maximal 3 Monaten.', 'https://www.laenderdaten.info/Amerika/Sankt-Bartholomaeus/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2019-01-24 13:59:00', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (188, 'São Tomé und Príncipe', 'São Tomé e Príncipe', 'Sao Tome and Principe', 'São Tomé e Príncipe', 'São Tomé e Príncipe', 'São Tomé en Príncipe', 'Wyspy Świętego Tomasza i Książęca', 'Santo Tomé y Príncipe', 'São Tomé e Príncipe', '', 'Сан-Томе и Принсипи', 'ST', 'passolution/countries/188/flag.png', 'passolution/countries/188/cover_image.jpg', '{\"w640\": \"passolution/countries/188/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/188/cover_image/1024w.jpg\"}', 'Africa', 'São Tomé', '197541', '964', '209', 'Semi-presidential republic', NULL, 'STD', '239', '33.3', '7', '64.9', 1, 'Visumpflichtige Personen benötigen ein Transitvisum. \r\nEs gelten folgende Ausnahmen: Reisende mit einem bestätigten Weiterflugticket in ein Drittland am selben Kalendertag brauchen kein Visum. Der Transitraum darf nicht verlassen werden und die Dokumente für das nächste Ziel sind erforderlich.', 'https://www.laenderdaten.info/Afrika/Sao-Tome-und-Principe/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:10:01', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (189, 'Saudi-Arabien', 'Al-´Arabiya as-Sa´udiya', 'Saudi Arabia', 'Arabie saoudite', 'Arabia Saudita', 'Saoedi-Arabië', 'Arabia Saudyjska', 'Arabia Saudita', 'Arábia Saudita', '', 'Саудовская Аравия', 'SA', 'passolution/countries/189/flag.png', 'passolution/countries/189/cover_image.jpg', '{\"w640\": \"passolution/countries/189/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/189/cover_image/1024w.jpg\"}', 'Asia', 'Riyadh', '28160273', '2149690', '2640', 'absolute monarchy', NULL, 'SAR', '966', '18.4', '3.3', '75.3', 1, 'Visumpflichtige Personen benötigen ein Transitvisum. \r\nEs gelten folgende Ausnahmen: Personen die über Dammam, Jeddah oder Riyadh mit einem gültigen Weiterflugticket und innerhalb von 12 Stunden weiterreisen und den Transitraum nicht verlassen benötigen kein Transitvisum. Es ist nur ein Transitstop in Saudi Arabien erlaubt.', 'https://www.laenderdaten.info/Asien/Saudi-Arabien/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:10:02', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (190, 'Schweden', 'Sverige', 'Sweden', 'Suède', 'Svezia', 'Zweden', 'Szwecja', 'Suecia', 'Suécia', '', 'Швеция', 'SE', 'passolution/countries/190/flag.png', 'passolution/countries/190/cover_image.jpg', '{\"w640\": \"passolution/countries/190/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/190/cover_image/1024w.jpg\"}', 'Europe', 'Stockholm', '9880604', '450295', '3218', 'Parliamentary constitutional monarchy', NULL, 'SEK', '46', '12', '9.4', '82.1', 1, 'Visumpflichtige Personen benötigen ein Transitvisum. Es gelten folgende Ausnahmen: Personen, die aus einem Nicht-Schengen-Land ohne Verlassen des Transitbereiches am selben Tag (kein Aufenthalt über Nacht) in ein weiteres Nicht-Schengen-Land weiterreisen und gültige Weiterreise Dokumente mit sich führen, benötigen kein Transitvisum.', 'https://www.laenderdaten.info/Europa/Schweden/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:10:02', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (191, 'Schweiz', 'Schweiz/Suisse/Svizzera/Svizra', 'Switzerland', 'Suisse', 'Svizzera', 'Zwitserland', 'Szwajcaria', 'Suiza', 'Suíça', '', 'Швейцария', 'CH', 'passolution/countries/191/flag.png', 'passolution/countries/191/cover_image.jpg', '{\"w640\": \"passolution/countries/191/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/191/cover_image/1024w.jpg\"}', 'Europe', 'Bern', '8179294', '41277', '0', 'Federal republic', NULL, 'CHF', '41', '10.5', '8.2', '82.6', 1, 'Visumpflichtige Personen benötigen ein Transitvisum. Es gelten folgende Ausnahmen: Personen, die innerhalb von 48 Stunden (Flughafen Zürich) bzw. am selben Tag (Flughafen Genf) im direkten Transit weiterreisen, über gültige Dokumente für die Weiterreise besitzen und den Transitraum nicht verlassen, brauchen kein Transitvisum.\r\nFür türkische Staatsbürger ist nur dann kein Transitvisum notwendig, wenn sie ein Visum oder eine Aufenthaltsgenehmigung für EU- und EFTA, Andorra, Japan, Kanada, Monaco, San Marino oder die USA besitzen.', 'https://www.laenderdaten.info/Europa/Schweiz/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:10:04', 28, '91.36.156.30', 1);
