INSERT INTO `webold_countries` VALUES (196, 'Simbabwe', 'Zimbabwe', 'Zimbabwe', 'Zimbabwe', 'Zimbabwe', 'Zimbabwe', 'Zimbabwe', 'Zimbabwe', 'Zimbabwe', '', 'Зимбабве', 'ZW', 'passolution/countries/196/flag.png', 'passolution/countries/196/cover_image.jpg', '{\"w640\": \"passolution/countries/196/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/196/cover_image/1024w.jpg\"}', 'Africa', 'Harare', '14546961', '390757', '0', 'Semi-presidential republic', 'ZWL', 'ZWL', '263', '31.9', '9.9', '58', 1, 'Visumpflichtige Personen benötigen ein Transitvisum. Es gelten folgende Ausnahmen: Reisende, die innerhalb von 6 Stunden am selben Kalendertag mit dem nächsten Anschluss weiterfliegen, den Transitraum nicht verlassen und über gültige Dokumente für die Weiterreise verfügen.', 'https://www.laenderdaten.info/Afrika/Simbabwe/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:10:02', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (197, 'Singapur', 'Singapore/Singapura/Xinjiapo/Singapur', 'Singapore', 'Singapour', 'Singapore', 'Singapore', 'Singapur', 'Singapur', 'Cingapura', '', 'Сингапур', 'SG', 'passolution/countries/197/flag.png', 'passolution/countries/197/cover_image.jpg', '{\"w640\": \"passolution/countries/197/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/197/cover_image/1024w.jpg\"}', 'Asia', 'Singapore', '5781728', '697', '193', 'parliamentary republic', NULL, 'SGD', '65', '8.4', '3.5', '85', 1, 'Visumpflichtige Personen benötigen ein Transitvisum. Es gelten folgende Ausnahmen: Reisende, die innerhalb von 24 Stunden mit dem nächsten Anschluss weiterfliegen, den Transitraum nicht verlassen und über gültige Dokumente für die Weiterreise verfügen. Wenn ein Transitvisum erforderlich ist, wird es bei der Ankunft ausgestellt und hat eine Gültigkeit von 96 Stunden. Dieses ermöglicht den Reisenden, den Flughafen zu verlassen.', 'https://www.laenderdaten.info/Asien/Singapur/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:10:02', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (198, 'Sint Maarten', 'Sint Maarten', 'Sint Maarten', 'Saint-Martin', 'Sint Maarten', 'Sint Maarten', 'Sint Maarten', 'San Martín', 'Sint Maarten', '', 'Синт-Мартен', 'SX', NULL, 'passolution/countries/198/cover_image.jpg', '{\"w640\": \"passolution/countries/198/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/198/cover_image/1024w.jpg\"}', 'America', 'Philipsburg', '41486', '34', '59', 'Republic (autonomous territory of the Kingdom of the Netherlands)', NULL, 'ANG', '1-721', '13.1', '5', '78.1', 1, 'Visumpflichtige Personen benötigen ein Transitvisum. Es gelten folgende Ausnahmen: Reisende, die am selben Kalendertag mit dem nächsten Anschluss weiterfliegen, den Transitraum nicht verlassen und über gültige Dokumente für die Weiterreise verfügen.', 'https://www.laenderdaten.info/Amerika/Sint-Maarten/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:10:03', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (199, 'Slowakei', 'Slovensko', 'Slovakia', 'Slovaquie', 'Slovacchia', 'Slowakije', 'Słowacja', 'Eslovaquia', 'Eslováquia', '', 'Словакия', 'SK', 'passolution/countries/199/flag.png', 'passolution/countries/199/cover_image.jpg', '{\"w640\": \"passolution/countries/199/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/199/cover_image/1024w.jpg\"}', 'Europe', 'Bratislava', '5445802', '49035', '0', 'parliamentary republic', NULL, 'EUR', '42', '9.8', '9.8', '77.1', 1, 'Grundsätzlich wird ein Transitvisum benötigt. Das Schengen-Flughafentransitvisum ermächtigt den Inhaber zur Durchreise durch das internationale Transitgebiet des Flughafens, wird jedoch von folgenden Nationalitäten nicht benötigt: Kanada, Australien, USA, Vereinigtes Königreich und alle EU-Länder.', 'https://www.laenderdaten.info/Europa/Slowakei/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:10:05', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (200, 'Slowenien', 'Slovenija', 'Slovenia', 'Slovénie', 'Slovenia', 'Slovenië', 'Słowenia', 'Eslovenia', 'Eslovênia', '', 'Словения', 'SI', 'passolution/countries/200/flag.png', 'passolution/countries/200/cover_image.jpg', '{\"w640\": \"passolution/countries/200/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/200/cover_image/1024w.jpg\"}', 'Europe', 'Ljubljana', '1978029', '20273', '47', 'parliamentary republic', NULL, 'EUR', '386', '8.3', '11.5', '78.2', 1, 'Visumpflichtige Personen benötigen ein Transitvisum. Es gelten folgende Ausnahmen: Für Reisende Staatsbürger der EU-Länder dürfen sich frei aufhalten. Reisende der Staatsbürgerschaften Afghanistan, Bangladesh, Congo (Dem. Rep.), Eritrea, Ethiopia, Ghana, Iran, Iraq, Nigeria, Pakistan, Somalia und Sri Lanka. dürfen mit einem Weiterreiseticket/ Weiterflugticket sich 24 Stunden im Transitbereich des Flughafens aufhalten.', 'https://www.laenderdaten.info/Europa/Slowenien/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:10:04', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (201, 'Somalia', 'Soomaaliya', 'Somalia', 'Somalie', 'Somalia', 'Somalië', 'Somalia', 'Somalia', 'Somália', '', 'Сомали', 'SO', 'passolution/countries/201/flag.png', NULL, NULL, 'Africa', 'Mogadishu', '10817354', '637657', '3025', 'Federal parliamentary republic', NULL, 'SOS', '252', '40', '13.3', '52.4', 1, 'Visumpflichtige Personen benötigen ein Transitvisum. Es gelten folgende Ausnahmen: Reisende, die am selben Kalendertag mit dem nächsten Anschluss weiterfliegen, den Transitraum nicht verlassen und über gültige Dokumente für die Weiterreise verfügen.', 'https://www.laenderdaten.info/Afrika/Somalia/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2023-12-08 08:35:13', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (202, 'Spanien', 'España', 'Spain', 'Espagne', 'Spagna', 'Spanje', 'Hiszpania', 'España', 'Espanha', '', 'Испания', 'ES', 'passolution/countries/202/flag.png', 'passolution/countries/202/cover_image.jpg', '{\"w640\": \"passolution/countries/202/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/202/cover_image/1024w.jpg\"}', 'Europe', 'Madrid', '48563476', '505370', '4964', 'Parliamentary constitutional monarchy', NULL, 'EUR', '34', '9.4', '9.1', '81.7', 1, 'Visumpflichtige Personen benötigen ein Transitvisum. Es gelten folgende Ausnahmen: Reisende mit den Staatsbürgerschaften der EU-Länder haben freien Aufenthalt. Reisende, die aus einem Nicht-Schengen-Land mit dem Flugzeug in ein anderes Nicht-Schengen-Land weiterfliegen, den Transitraum nicht verlassen und über gültige Dokumente für die Weiterreise verfügen. Reisende mit den Staatsbürgerschaften von Afghanistan, Bangladesch, Kamerun, Kongo (Dem. Rep.), Cote d\'Ivoire, Kuba, Dschibuti, Eritrea, Äthiopien, Gambia, Ghana, Guinea, Guinea-Bissau, Indien, Iran, Irak, Liberia, Mali, Nigeria, Pakistan, Sierra Leone, Somalia, Sri Lanka, Syrien und Togo können mit einem Weiterreiseticket/ Weiterflugticket sich bis zu 24 Stunden visumfrei im Transitbereich des Flughafens aufhalten, wenn sie aus einem Nicht-Schengen Land kommen und in ein Nicht-Schengen Land weiterreisen.', 'https://www.laenderdaten.info/Europa/Spanien/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:10:04', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (203, 'Sri Lanka', 'Sri Lanka/Ilankai', 'Sri Lanka', 'Sri Lanka', 'Sri Lanka', 'Sri Lanka', 'Sri Lanka', 'Sri Lanka', 'Sri Lanka', '', 'Шри-Ланка', 'LK', 'passolution/countries/203/flag.png', 'passolution/countries/203/cover_image.jpg', '{\"w640\": \"passolution/countries/203/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/203/cover_image/1024w.jpg\"}', 'Asia', 'Colombo', '22235000', '65610', '1340', 'Presidential republic', NULL, 'LKR', '94', '15.5', '6.2', '76.8', 1, 'Visumpflichtige Personen benötigen ein Transitvisum. Dieses berechtigt zu einem Aufenthalt von maximal 48 Stunden und kann unter www.eta.gov.lk/slvisa beantragt werden.', 'https://www.laenderdaten.info/Asien/Sri-Lanka/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:10:04', 28, '91.36.156.30', 1);
