INSERT INTO `webold_countries` VALUES (227, 'Tschechien', 'Česká republika', 'Czech Republic', 'Tchéquie', 'Cecoslovacchia', 'Tsjechië', 'Czechy', 'República Checa', 'República Checa', '', 'Чехия', 'CZ', 'passolution/countries/227/flag.png', 'passolution/countries/227/cover_image.jpg', '{\"w640\": \"passolution/countries/227/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/227/cover_image/1024w.jpg\"}', 'Europe', 'Prague', '10644842', '78867', '0', 'parliamentary republic', NULL, 'CZK', '42', '9.5', '10.4', '78.6', 1, 'Visumpflichtige Personen benötigen ein Transitvisum. Es gelten folgende Ausnahmen: Reisende mit den Staatsbürgerschaften der EU-Länder haben freien Aufenthalt. Reisende, die aus einem Nicht-Schengen-Land mit dem Flugzeug in ein anderes Nicht-Schengen-Land weiterfliegen, den Transitraum nicht verlassen und über gültige Dokumente für die Weiterreise verfügen. Nur wenn türkische Staatsangehörige über eine gültige Aufenthaltsgenehmigung für ein Schengenland oder die USA verfügen, können sie von der Transiterleichterung Gebrauch machen. Reisende mit den Staatsbürgerschaften vonAfghanistan, Bangladesh, Chad, Congo (Dem. Rep.), Egypt, Eritrea, Ethiopia, Ghana, India, Iran, Iraq, Kyrgyzstan, Lebanon, Libya, Mali, Mauritania, Niger, Nigeria, Pakistan, Somalia, South Sudan, Sri Lanka, Sudan, Syria, Turkey, Turkmenistan und Yemen können mit einem Weiterreiseticket/ Weiterflugticket sich bis zu 24 Stunden visumfrei im Transitbereich des Flughafens aufhalten, wenn sie aus einem Nicht-Schengen Land kommen und in ein Nicht-Schengen Land weiterreisen.', 'https://www.laenderdaten.info/Europa/Tschechien/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:10:08', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (228, 'Tunesien', 'Tunis/Tunisie', 'Tunisia', 'Tunisie', 'Tunisia', 'Tunesië', 'Tunezja', 'Túnez', 'Tunísia', '', 'Тунис', 'TN', 'passolution/countries/228/flag.png', 'passolution/countries/228/cover_image.jpg', '{\"w640\": \"passolution/countries/228/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/228/cover_image/1024w.jpg\"}', 'Africa', 'Tunis', '11134588', '163610', '1148', 'parliamentary republic', NULL, 'TND', '216', '16.4', '6', '76.1', 1, 'Visumpflichtige Personen benötigen ein Transitvisum. Es gelten folgende Ausnahmen: Reisende, die innerhalb von 48 Stunden mit dem nächsten Anschluss weiterfliegen, den Transitraum nicht verlassen und über gültige Dokumente für die Weiterreise verfügen. Staatsangehörige von Libanon und Syrien dürfen sich 24 Stunden visumfrei aufhalten, wenn sie  mit dem nächsten Anschluss weiterfliegen, den Transitraum nicht verlassen und über gültige Dokumente für die Weiterreise verfügen. Transit ohne Visum gilt nicht für folgende Nationalitäten: Bolivien, Kolumbien, Ghana, Israel, Neuseeland, Peru. Transit ohne Visum gilt nicht, wenn Staatsangehörige Chinas, Iran, Philippinen und Singapur mit einem normalen Reisepass reisen.', 'https://www.laenderdaten.info/Afrika/Tunesien/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:10:11', 28, '91.36.156.30', 1);
