INSERT INTO `webold_countries` VALUES (243, 'Vereinigtes Königreich', 'United Kingdom', 'United Kingdom', 'Royaume-Uni', 'Regno Unito', 'Verenigd Koninkrijk', 'Zjednoczone Królestwo', 'Reino Unido', 'Reino Unido', '', 'Великобритания', 'GB', 'passolution/countries/243/flag.png', 'passolution/countries/243/cover_image.jpg', '{\"w640\": \"passolution/countries/243/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/243/cover_image/1024w.jpg\"}', 'Europe', 'London', '64430428', '243610', '12429', 'Parliamentary constitutional monarchy', NULL, 'GBP', '44', '12.1', '9.4', '80.7', 1, 'Visumpflichtige Personen benötigen ein Transitvisum. Es gelten folgende Ausnahmen: Viele ansonsten visumpflichtige (genaue Informationen von den konsularischen Vertretungen) Reisende, die am selben Kalendertag über die Flughäfen Manchester (MAN), London Gatwick (LGW) oder London Heathrow (LHR) mit dem nächsten Anschluss weiterfliegen, den Transitraum nicht verlassen und über gültige Dokumente für die Weiterreise verfügen. Türkische Staatsbürger brauchen ein Visum und sind in der Regel von dieser Transiterleichterung ausgeschlossen.', 'https://www.laenderdaten.info/Europa/Vereinigtes-Koenigreich/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:10:12', 28, '91.36.156.30', 1);
