INSERT INTO `webold_countries` VALUES (248, 'Zentralafrikanische Republik', 'Centrafrique/Bê-Afrîka', 'Central African Republic', 'République centrafricaine', 'Repubblica Centrafricana', 'Centraal-Afrikaanse Republiek', 'Republika Środkowoafrykańska', 'República Centroafricana', 'República Centro-Africana', '', 'Центральноафриканская Республика', 'CF', 'passolution/countries/248/flag.png', 'passolution/countries/248/cover_image.jpg', '{\"w640\": \"passolution/countries/248/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/248/cover_image/1024w.jpg\"}', 'Africa', 'Bangui', '5507257', '622984', '0', 'Presidential republic', NULL, 'XAF', '236', '34.7', '13.5', '52.3', 1, 'Grundsätzlich wird ein Transitvisum benötigt. Es gelten folgende Ausnahmen: Reisende, die ein Visum benötigen, jedoch mit dem selben Flugzeug weiterfliegen, über gültige Dokumente für die Weiterreise verfügen und den Transitraum nicht  verlassen, brauchen kein Visum.', 'https://www.laenderdaten.info/Afrika/Zentralafrikanische-Republik/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:10:13', 28, '91.36.156.30', 1);
INSERT INTO `webold_countries` VALUES (249, 'Zypern', 'Kýpros/Kibris', 'Cyprus', 'Chypre', 'Cipro', 'Cyprus', 'Cypr', 'Chipre', 'Chipre', '', 'Кипр', 'CY', 'passolution/countries/249/flag.png', 'passolution/countries/249/cover_image.jpg', '{\"w640\": \"passolution/countries/249/cover_image/640w.jpg\", \"w1024\": \"passolution/countries/249/cover_image/1024w.jpg\"}', 'Asia', 'Nicosia', '1205575', '9251', '648', 'Presidential democracy', NULL, 'EUR', '357', '11.4', '6.7', '78.7', 1, 'Visumpflichtige Personen benötigen ein Transitvisum. Es gelten folgende Ausnahmen: Reisende mit den Staatsbürgerschaften der EU-Länder haben freien Aufenthalt. Reisende, die innerhalb von 24 Stunden mit dem nächsten Anschluss weiterfliegen, den Transitraum nicht verlassen und über gültige Dokumente für die Weiterreise verfügen. Nur wenn türkische Staatsbürger Inhaber eines Schengen-Visums oder einer Aufenthaltserlaubnis für einen EU-Staat oder für einen Staat der Europäischen Freihandelsassoziation oder für Andorra, Kanada, Japan, San Marino oder USA sind, brauchen sie kein Transitvisum. Reisende mit den Staatsbürgerschaften von Afghanistan, Bangladesh, Congo (Dem. Rep.), Eritrea, Ethiopia, Ghana, Iran, Iraq, Nigeria, Pakistan, Somalia und Sri Lanka können mit einem Weiterreiseticket/ Weiterflugticket sich bis zu 24 Stunden visumfrei im Transitbereich des Flughafens aufhalten, wenn sie aus einem Nicht-Schengen Land kommen und in ein Nicht-Schengen Land weiterreisen.', 'https://www.laenderdaten.info/Asien/Zypern/index.php', 99, NULL, '2019-01-23 08:13:00', 1, '127.0.0.1', '2025-03-03 11:10:17', 28, '91.36.156.30', 1);
